window.GENSHIN_STORY = {"schema":1,"volumes":[{"version":"1.0","major":1,"minor":0,"title":"序章第一至三幕；第一章第一至二幕","chapter":"序章第1至3幕与第一章第1至2幕","sections":[{"id":"v1.0-s0","title":"序章第一幕：捕风的异乡人","kind":"chapter","html":"\u003cp\u003e在抵达提瓦特之前，一对旅行世界的双子正要离开此地，却被一位陌生的神明截住。交锋中，兄妹失散，旅行者的力量被封印。漫长的沉睡之后，旅行者在海边救起派蒙；从此，一人为寻找血亲，一人作向导，踏上拜访七神的道路。\u003c/p\u003e\n\u003cp\u003e他们在蒙德的风神像前获得风元素之力，又在低语森林撞见一名吟游诗人与巨龙相会。诗人似乎想安抚巨龙，旅行者却无意惊动了它，只留下染着不祥气息的泪滴结晶。侦察骑士安柏把两人引入自由之城。就在他们初见城邦时，被称为「风魔龙」的巨龙掀起风暴。旅行者借风而起，击退了它，也被西风骑士团的琴团长注意到。琴、凯亚与丽莎调查后发现，城外「四风守护」的庙宇力量正受扰乱；旅行者协助清除异常，得以参与蒙德的危机。\u003c/p\u003e\n"},{"id":"v1.0-s1","title":"序章第二幕：为了没有眼泪的明天","kind":"chapter","html":"\u003cp\u003e骑士团并不愿把龙当成必须处死的怪物：它原名特瓦林，曾是蒙德的守护者。提出杀龙方案的愚人众外交官则显示，至冬国也在借危机介入。旅行者手中的结晶会伤害拥有神之眼的人，却能被旅行者净化。这异于常人的能力，让那名吟游诗人——温迪——看见拯救特瓦林的可能。\u003c/p\u003e\n\u003cp\u003e温迪说明，特瓦林长期受毒血与深渊教团的影响，误以为自己遭人背弃；他想用旧日的「天空之琴」唤回龙的记忆。取琴的行动却先遭愚人众截胡，旅行者与温迪又被误作窃贼。晨曦酒庄的迪卢克暗中接应，琴也暂放下代理团长的身份加入他们。众人夺回琴，以净化的龙泪修复它，在摘星崖唤来了特瓦林。然而深渊法师现身，重新挑起龙的猜疑；琴弦折断，特瓦林飞向被结界封锁的旧蒙德遗迹。\u003c/p\u003e\n"},{"id":"v1.0-s2","title":"序章第三幕：巨龙与自由之歌","kind":"chapter","html":"\u003cp\u003e迪卢克追出深渊法师的行踪，温迪由此找到突破封锁的办法。众人进入风龙废墟——那也是旧蒙德的残骸——追上特瓦林。旅行者清除了折磨巨龙的毒与深渊力量。获救的特瓦林问温迪，为什么不再命令自己守护他。温迪给出的答复，正是这座城的信念：即使命令它「自由」，那也不是真正的自由。巨龙终于可以依自己的意志飞翔，蒙德的风灾得以平息。\u003c/p\u003e\n\u003cp\u003e胜利之后，另一场袭击毫无预警地发生。温迪在教堂外遭愚人众执行官「女士」伏击，被夺走体内的\u003cstrong\u003e神之心\u003c/strong\u003e。旅行者也被制服。温迪随后在风起地承认，自己就是风神巴巴托斯；神之心是神明与天空岛联系的象征。他对冰之女皇为何采取这种手段没有给出定论，只提到五百年前的一场灾厄改变了诸神之间的关系。寻找血亲的旅途不能止步，温迪指引旅行者去璃月，赶上岩神一年一度的请仙典仪。\u003c/p\u003e\n"},{"id":"v1.0-s3","title":"第一章第一幕：浮世浮生千岩间","kind":"chapter","html":"\u003cp\u003e旅行者赶到璃月港，本以为能向岩王帝君问路，却在请仙典仪上亲眼看见神明的躯体从天而降。天权星凝光下令封锁现场，来自异乡的旅行者险些被当成嫌疑人。出手解围的是愚人众执行官「公子」达达利亚。他自称并无敌意，交给旅行者百无禁忌箓，让他们把帝君遇害的消息先告知仙人。\u003c/p\u003e\n\u003cp\u003e旅行者先后见到削月筑阳真君、理水叠山真君、留云借风真君与降魔大圣魈。仙人们对帝君之死震惊且愤怒，璃月七星却紧锁帝君遗体，不容外人查验。仙人与人治的璃月之间，猜疑开始增长。公子看似帮助旅行者洗清嫌疑，实则也在留意他们为何执意要见神明。\u003c/p\u003e\n"},{"id":"v1.0-s4","title":"第一章第二幕：辞行久远之躯","kind":"chapter","html":"\u003cp\u003e公子把旅行者引荐给往生堂客卿钟离。钟离要为「岩王帝君」筹办送仙典仪，旅行者则希望借此接近帝君的仙体。于是三人穿行璃月市井，选取夜泊石、调制霓裳花香膏、向萍姥姥借涤尘铃、备下纸鸢，又为不卜庐寻找永生香。钟离熟知古礼、仙人与岩神的往事，却常忘带摩拉；费用多由公子承担。\u003c/p\u003e\n\u003cp\u003e这些琐碎的准备，使旅行者看见另一幅璃月：有人惋惜帝君陨落，有人照常经营生活；古老契约仍在，但这座港口也正由普通人支撑。公子对典仪的慷慨并不能抹去他的目的。他从情报中得知，七星把仙体藏在黄金屋；当他试探旅行者时，旅行者拒绝交出所知。与此同时，凝光邀请旅行者登上群玉阁。送仙典仪尚未开始，帝君之死也仍无答案，璃月的几股力量已向同一个谜团逼近。\u003c/p\u003e\n"},{"id":"v1.0-s5","title":"同期值得留意的世界线索","kind":"world","html":"\u003cul\u003e\n\u003cli\u003e\u003cstrong\u003e「时与风」\u003c/strong\u003e：蒙德外海无名小岛的日晷与千风神殿留下时间和风相连的古老痕迹。1.0 尚不能据此断定其主人或完整历史。\u003c/li\u003e\n\u003cli\u003e\u003cstrong\u003e「古云有螭」与「靖世九柱」\u003c/strong\u003e：璃月山野散有被封印的古老力量与遗迹。它们说明帝君与仙人守护的土地，曾经历远不止眼前这场政治危机的战争。\u003c/li\u003e\n\u003cli\u003e\u003cstrong\u003e已知的三股势力\u003c/strong\u003e：西风骑士团试图救龙，深渊教团操纵龙的痛苦，愚人众则追逐神之心。三者目的并不相同；到此时，旅行者尚不知深渊教团的统领是谁，也不知冰之女皇收集神之心究竟为了什么。\u003c/li\u003e\n\u003c/ul\u003e\n"},{"id":"v1.0-s6","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e血亲身在何处？陌生神明是谁？风神的神之心被夺后会怎样？璃月的岩王帝君究竟为何坠落？这些问题留待后续版本自然展开。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.0\"\u003e1.0 版本收录任务\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Outlander_Who_Caught_the_Wind\"\u003e捕风的异乡人\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/For_a_Tomorrow_Without_Tears\"\u003e为了没有眼泪的明天\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Song_of_the_Dragon_and_Freedom\"\u003e巨龙与自由之歌\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Of_the_Land_Amidst_Monoliths\"\u003e浮世浮生千岩间\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Farewell,_Archaic_Lord\"\u003e辞行久远之躯\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.1","major":1,"minor":1,"title":"第一章第三幕：迫近的客星","chapter":"第一章第三幕","sections":[{"id":"v1.1-s0","title":"本版本的重要结论","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e从 \u003ca href=\"./1.0-%E5%BA%8F%E7%AB%A0%E7%AC%AC1%E8%87%B33%E5%B9%95%E4%B8%8E%E7%AC%AC%E4%B8%80%E7%AB%A0%E7%AC%AC1%E8%87%B32%E5%B9%95-%E6%8D%95%E9%A3%8E%E7%9A%84%E5%BC%82%E4%B9%A1%E4%BA%BA%E8%87%B3%E8%BE%9E%E8%A1%8C%E4%B9%85%E8%BF%9C%E4%B9%8B%E8%BA%AF.md\"\u003e1.0\u003c/a\u003e 接续；只叙述本版本已经揭示的事。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e凝光邀请旅行者登上群玉阁。她并未直接宣判愚人众的阴谋，而是让客人看见她收集的情报。旅行者循线发现，愚人众正在大量仿制百无禁忌箓；与此同时，仙人与璃月七星因帝君的「遇害」几乎兵戎相见。钟离仍在准备送仙典仪，似乎置身风暴之外。\u003c/p\u003e\n\u003cp\u003e公子趁乱闯入黄金屋，目标是岩王帝君仙体中的神之心。旅行者赶到，双方交手；公子先后动用邪眼和魔王武装，仍未得逞。当他从仙体中探取神之心却一无所获时，便误疑旅行者先行取走了它。受挫后，他动用仿制的符箓唤醒被岩神镇压于孤云阁海底的漩涡之魔神奥赛尔，企图逼真正的岩神现身。璃月港立刻面临灭顶之灾。\u003c/p\u003e\n\u003cp\u003e凝光、刻晴、众仙人与旅行者暂释分歧，在群玉阁上以归终机迎击奥赛尔。愚人众袭击炮台，旅行者在仙人相助下守住阵地；然而魔神的反击摧毁了炮台。凝光最终舍弃自己经营多年的空中宫殿，以坠落的群玉阁重创奥赛尔，将其重新压回海中。这一战既是璃月人的胜利，也迫使仙人承认：帝君不在场时，凡人仍能守护这座港口。\u003c/p\u003e\n\u003cp\u003e战后，旅行者在北国银行撞见钟离、女士和公子。钟离承认自己就是岩神摩拉克斯；请仙典仪上的「死亡」由他亲自安排。他想用一次真正的危机检验璃月是否已能告别神明的直接统治，并预留了若人们失败就出手的后路。结果使他确信，璃月进入了人的时代。作为与冰之女皇订下的「终结一切契约的契约」的一部分，他把神之心交给女士。契约的交换条件，他没有说出；公子也发现自己被同僚与岩神蒙在鼓里。\u003c/p\u003e\n\u003cp\u003e送仙典仪终于举行。璃月人以自己的方式纪念岩王帝君，旅行者却知道，他只是从神座退到了人群。面对刻晴询问所求的报酬，旅行者要的不是珍宝，而是帮忙张贴寻找血亲的寻人启事。钟离指向下一站稻妻：那里的雷神推行「眼狩令」，国家又被风暴与锁国政策封闭。\u003c/p\u003e\n\u003cp\u003e神之心可以被夺取，也可以由神明主动交出；七神与至冬女皇之间存在更大的交易。璃月的神与人完成了一次权力交接，但女皇收集神之心的最终目的依旧未知。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_New_Star_Approaches\"\u003e迫近的客星任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.1\"\u003e1.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.2","major":1,"minor":2,"title":"无魔神任务：龙脊雪山与白垩之子","chapter":"无主线","sections":[{"id":"v1.2-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 这一版本没有新增魔神任务。以下是与世界观关系较深、且在本版本就可得知的剧情。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e蒙德南方的龙脊雪山埋着巨龙杜林的遗骸。它曾在数百年前袭击蒙德，最终被特瓦林击败；至今，山中的地脉与遗骨仍带着诡异的活性。旅行者受炼金术士阿贝多之邀，参与对一柄奇异魔剑的观察。剑与杜林残留的力量彼此呼应，似乎能吸收雪山的生命能量。阿贝多反复测试旅行者的元素亲和力和抗侵蚀能力，既像严谨的学者，也像在寻找一面能映照自己秘密的镜子。\u003c/p\u003e\n\u003cp\u003e阿贝多自称是莱茵多特创造的生命，并暗示自己的诞生与这条龙有某种共同源头。他对自己若失控会造成什么后果抱有警惕，甚至请旅行者在那一天到来时阻止他。这是一个尚未兑现的预感；1.2 没有解释莱茵多特的全部身份，也没有判定阿贝多必定会成为敌人。\u003c/p\u003e\n\u003cp\u003e雪山的探索也揭开另一层历史：古国沙尔·芬德尼尔曾在此存续，后来在严寒、灾变与神秘的天外之物影响下覆灭。如今看似荒凉的山地，曾是有人祈祷、建城与记述命运的地方。古国覆灭的完整因果，此时仍未清楚。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.2\"\u003e1.2 版本任务列表\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Dragonspine\"\u003e龙脊雪山\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Chalk_Prince_and_the_Dragon\"\u003e白垩与黑龙\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.3","major":1,"minor":3,"title":"第一章第四幕·序幕：拾枝者·戴因斯雷布","chapter":"第一章第四幕序幕","sections":[{"id":"v1.3-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e旅行者在蒙德受冒险家协会所托，追查与深渊教团有关的线索，于是结识了戴因斯雷布。此人不属于骑士团，也不急于说明自己的来历；他熟悉深渊教团的行动，却对七神抱有显著戒心。他向旅行者提出问题，像在衡量这个寻找血亲的异乡人会如何看待神、土地与自身命运。\u003c/p\u003e\n\u003cp\u003e两人走过蒙德的遗迹与风龙废墟，追寻深渊使徒的踪迹。戴因斯雷布在旧蒙德感到某种熟悉的气息，旅行者也短暂捕捉到与失散血亲有关的痕迹。线索随即中断。戴因斯雷布并未揭开全部所知，只留下一个越来越明确的预感：深渊教团与旅行者要寻找的人，关系比旁人想象得更近。\u003c/p\u003e\n\u003cp\u003e海灯节期间，旅行者见到魈日夜清除魔神残留的怨念。璃月战胜奥赛尔之后，旧时代的战争并未自动结束；有人仍在为凡人的安宁承担漫长代价。这段见闻不改变寻找血亲的主线，却补上「仙人守护璃月」在日常中的分量。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.3\"\u003e1.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Bough_Keeper:_Dainsleif\"\u003e拾枝者·戴因斯雷布\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.4","major":1,"minor":4,"title":"第一章第四幕：我们终将重逢","chapter":"第一章第四幕","sections":[{"id":"v1.4-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e一桩寻宝委托，把旅行者引入深渊教团盘踞的遗迹。倒悬的风神像、死去的盗宝团成员与突然现身的深渊使徒，让这次调查显出近乎亵渎神明的意味。戴因斯雷布再度加入追查。众人从教团文书中拼出计划：以昔日岩神封印的奥赛尔为素材，以倒悬神像为躯干，再装入第一台「耕地机」的眼睛，造出能够与天上力量抗衡的机械神明。\u003c/p\u003e\n\u003cp\u003e戴因斯雷布这才说出「耕地机」的真正来历。它们就是散落提瓦特各地的遗迹守卫，曾是无神之国坎瑞亚的战争机器。约五百年前，坎瑞亚覆灭；其技术与人民留下的残骸，成了今日许多人眼中的怪物。旅行者因此第一次把眼前的深渊灾祸，与一场被神明毁灭的古国联系起来。\u003c/p\u003e\n\u003cp\u003e为了阻止教团，众人先救下遭仪式侵蚀的北风之狼，随后在风龙废墟找到首台耕地机，戴因斯雷布取走了关键的「眼睛」。他们返回遗迹，准备毁去倒悬神像，深渊使徒却在那里等候。就在戴因斯雷布即将制服对手的一刻，一把熟悉的剑挡下了他——旅行者失散的血亲终于现身。\u003c/p\u003e\n\u003cp\u003e重逢没有带来归家。血亲认识戴因斯雷布，称他为坎瑞亚的「末光之剑」，并指出他因诅咒长生，眼看故国之人化为怪物。血亲如今站在深渊教团一边，认为与「命运」的战争尚未结束；旅行者必须走遍提瓦特，亲眼看见世界的真相，才会理解自己的选择。说罢，血亲随深渊使徒踏入传送门。戴因斯雷布追了进去，旅行者慢了一步，只能眼看入口关闭。\u003c/p\u003e\n\u003cp\u003e旅行者并非再无方向。他们已知道血亲仍在提瓦特，知道坎瑞亚、深渊与五百年前的灾难密不可分，也知道对方走过一条自己尚未走完的路。派蒙劝他们继续前行；下一站，仍是雷暴中的稻妻。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/We_Will_Be_Reunited\"\u003e我们终将重逢任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.4\"\u003e1.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.5","major":1,"minor":5,"title":"无魔神任务：若陀龙王与磨损","chapter":"无主线","sections":[{"id":"v1.5-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本没有新增魔神任务；钟离的第二幕传说任务对理解岩神与古老契约尤其重要。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e璃月矿工失踪、岩层异动，把旅行者与钟离引向伏龙树。树下封印的是若陀龙王，昔日岩神的盟友。岩神赋予它观世之目，二者曾并肩守护璃月；但若陀与地脉紧密相连，岁月使记忆和情感不断受损。人类开采山脉又加剧了它的痛苦。最终，若陀失去与岩神同行的初心，双方不得不以封印作结。\u003c/p\u003e\n\u003cp\u003e如今若陀的一部分愤怒与记忆化作人形，试图打破封印；另一部分仍记得旧日情谊，帮助钟离与旅行者再次镇压它。钟离把这份不可回避的消磨称为\u003cstrong\u003e磨损\u003c/strong\u003e。它不只是衰老，更会侵蚀长生者的记忆、意志与自我。连神明也无法置身时间之外。钟离没有把退位说成摆脱一切责任：曾经立下的契约仍有重量，而旧友也只能在封印与记忆中告别。\u003c/p\u003e\n\u003cp\u003e这段故事让旅行者看见，魔神战争的胜利者也付出了代价。璃月能走向人的时代，并非因为神的力量永不衰退，而是因为守护不能永远只压在神和仙人身上。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.5\"\u003e1.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/No_Mere_Stone\"\u003e匪石：钟离传说任务第二幕\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"1.6","major":1,"minor":6,"title":"第二章·序幕：振袖秋风问红叶","chapter":"第二章序幕","sections":[{"id":"v1.6-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e旅行者要去稻妻，却面临横海雷暴与锁国令。稻妻出身的阿幸劝他们三思，最终指向能穿越险海的南十字船队。北斗的「南十字武斗会」提供了船票；旅行者以不借神之眼也能运使元素的身手夺得冠军，同时结识船上的流浪武士枫原万叶。\u003c/p\u003e\n\u003cp\u003e万叶带着一枚失去光芒的神之眼。它属于一位故友：那人曾向雷电将军的「无想的一刀」发起挑战，死于御前决斗。万叶抢走神之眼，逃出了稻妻。他四处寻找能让它重新发光的人，并非只为完成遗物的使命，也是不愿故友敢于直面雷霆的愿望就此熄灭。武斗会的奖品被盗，旅行者与万叶追上盗贼，却无人能令那枚神之眼复苏。\u003c/p\u003e\n\u003cp\u003e北斗允诺送旅行者出海。万叶的故事则给雷神治下的稻妻添上第一道真实的伤口：眼狩令不只是一条远方的法令，它能夺去人的愿望，也能夺去性命。大海彼岸等待旅行者的，是无法靠武斗会胜利就解开的政治与信仰之结。\u003c/p\u003e\n\u003cp\u003e金苹果群岛的限时冒险里，艾莉丝为可莉布置了一场跨海的谜题。她远在别处，仍能调动岛屿与机关，把爱意藏成一次历险。此时所知只有她非同寻常的能力与对女儿的牵挂，不必先替她在更大的世界史中安放位置。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Autumn_Winds,_Scarlet_Leaves\"\u003e振袖秋风问红叶任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/1.6\"\u003e1.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.0","major":2,"minor":0,"title":"第二章第一至二幕：不动鸣神，恒常乐土；无念无想，泡影断灭","chapter":"第二章第1至2幕","sections":[{"id":"v2.0-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e北斗的船穿过雷暴，把旅行者送到稻妻。这里的「锁国令」严控出入，「眼狩令」则要收缴神之眼，嵌进雷电将军的千手百眼神像。旅行者原本只想见雷神寻找血亲线索，社奉行的托马与神里绫华却请他们先看见法令落在人身上的样子。\u003c/p\u003e\n\u003cp\u003e失去神之眼的手岛忘了多年等待的缘由；武士黑泽曾为人垫付粮食，却忘记自己为何负债；以武艺为信念的土门在失去神之眼后几乎崩溃。旅行者由此明白，被夺走的不只是施展元素的工具，也可能是一个人最强烈的愿望与支撑。绫华带他们接触反抗者，宵宫协助营救被关押的烟花匠，稻妻人在严令之下仍以各自方式保护彼此。\u003c/p\u003e\n\u003cp\u003e托马随后被选作「第一百枚」神之眼的献祭对象。旅行者冲向仪式，亲手从将军面前救下他。雷电将军把旅行者拖入神秘的「一心净土」；旅行者在那里第一次面对压倒性的神威，也听见将军将永恒置于凡人愿望之上的意志。八重神子插手使他们得以脱身，但稻妻城已无容身之地。\u003c/p\u003e\n\u003cp\u003e旅行者转往海祇岛，加入珊瑚宫心海统率的反抗军。前线军士哲平对他们热情相待；反抗军虽守住阵线，却远不足以正面推翻将军的统治。战场另一侧，幕府将领九条裟罗同样坚信自己在守护稻妻。这场战争不只关乎一条法令，也关乎各方对「永恒」的理解。\u003c/p\u003e\n\u003cp\u003e神樱大祓揭示鸣神岛结界与污秽的循环。巫女花散里的记忆牵连古老的狐斋宫；净化神樱既是守护土地，也是在与已逝者的残影告别。八酝岛上，魔神奥罗巴斯的遗骸与无想刃狭间则证明，稻妻的和平建在神明战争的创伤之上。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务章节与版本记录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.0\"\u003e2.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.1","major":2,"minor":1,"title":"第二章第三幕：千手百眼，天下人间","chapter":"第二章第三幕","sections":[{"id":"v2.1-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e反抗军的战果背后，悄悄流入前线的「邪眼」让普通士兵获得力量，却以生命为代价。哲平想追上旅行者的脚步，使用邪眼后急速衰老，最终死去。旅行者循线闯入愚人众的邪眼工厂，愤怒中遭散兵设局。八重神子拿雷神的神之心换回旅行者的性命；神之心为何在她手中、她与雷神的关系，随后才逐渐清晰。\u003c/p\u003e\n\u003cp\u003e神子告诉旅行者，世人所见的「雷电将军」是奉行永恒程序的人偶，真正的雷神影长久隐居一心净土。影曾与姐姐真共同守护稻妻；真死后，她惧怕一切终将失去，便以静止来对抗磨损。神子希望旅行者把人的愿望带到影面前，而非只在现实战场上与人偶厮杀。\u003c/p\u003e\n\u003cp\u003e旅行者和神子追查出九条家对将军隐瞒战况、配合愚人众推动眼狩令。九条裟罗知晓真相后决意求证，却在天守阁被女士击倒。旅行者向女士发起御前决斗，并赢下战斗；雷电将军随即按决斗法则斩杀女士。旅行者离开天守阁时，仍遭将军追击。万叶挡在刀前，故友失色的神之眼在危急一刻重新亮起，帮他接住了那道曾夺走友人性命的雷光。\u003c/p\u003e\n\u003cp\u003e神子引旅行者再入一心净土。面对影，旅行者承载了神像中无数被夺走的愿望，再度起身。影终于看见：永恒若要保护稻妻，就不能以抹去人心为代价。她废止眼狩令，反抗军与幕府的战事至此出现转机。锁国令与她对永恒的疑问却没有在这一战里全部解决。\u003c/p\u003e\n\u003cp\u003e清籁岛的雷暴与海祇岛的古老祭祀，都说明稻妻各岛并未因幕府建立而拥有相同的历史。海祇岛居民供奉奥罗巴斯，对雷神和幕府的态度也因此复杂；这一背景让反抗军的立场更易理解。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务章节与版本记录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.1\"\u003e2.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.2","major":2,"minor":2,"title":"无魔神任务：鹤观的雾与阿瑠","chapter":"无主线","sections":[{"id":"v2.2-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本的重要世界任务是鹤观的「雾海纪行」。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者踏入终年被雾包围的鹤观，遇到少年阿瑠。他像在等待一场祭典，又似乎不知道岛上的日子早已重复了太久。随着栖木与羽毛的仪式被逐一解开，旅行者看见一段惨烈旧史：鹤观的先民崇奉雷鸟，将能以歌声打动雷鸟的阿瑠献作祭品。他们以为这是虔诚，雷鸟却从未要求这份牺牲。它归来后发现阿瑠已死，在愤怒与悲伤中毁灭鹤观。\u003c/p\u003e\n\u003cp\u003e岛上的浓雾与循环保留着往日的碎片，阿瑠的身影也被困在重复的祭礼里。旅行者协助他唱完未能传达给雷鸟的歌，让这段执念终于得以散去。雷鸟后来成为稻妻另一场雷灾的源头，但在鹤观，它首先是一个未能理解人类、又失去唯一知音的存在。\u003c/p\u003e\n\u003cp\u003e这段支线给「神明、眷属与人」的关系添上一层阴影：人们以神的名义献祭，神却未必知情；灾祸也可能来自双方永远错开的心意。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.2\"\u003e2.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Through_the_Mists\"\u003e雾海纪行\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.3","major":2,"minor":3,"title":"无魔神任务：皑尘与雪影","chapter":"无主线","sections":[{"id":"v2.3-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本限时剧情发生在龙脊雪山，承接 1.2 对阿贝多与杜林的疑问。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e雪山里出现了一个容貌几乎与阿贝多相同的人。他借雪山与杜林的力量制造混乱，让同行者难辨真假。阿贝多最终对旅行者谈起莱茵多特的「原初之人计划」：自己是炼金术造物，而在成功以前，可能还有被视作失败品的生命。若一个生命被其创造者舍弃，它仍会渴望名字、位置与被承认的资格。冒牌者的敌意便从这份被剥夺感中长出。\u003c/p\u003e\n\u003cp\u003e旅行者与阿贝多合力度过危机，但故事没有把每个相似身影的去向彻底说死。阿贝多仍把旅行者视为必要的见证者：倘若某天他本人越过无法回头的界线，希望有人能认出真正的危险。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.3\"\u003e2.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Shadows_Amidst_Snowstorms\"\u003e皑尘与雪影\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.4","major":2,"minor":4,"title":"间章第一幕：风起鹤归；渊下宫","chapter":"间章第一幕","sections":[{"id":"v2.4-s0","title":"重要世界支线：渊下宫","kind":"world","html":"\u003cp\u003e凝光要重建群玉阁。旅行者在寻材途中结识申鹤，一个自幼在山中由仙人抚养、言行与人间格格不入的女子。她曾被至亲舍弃，又受山中生活与红绳约束情绪，因而难以相信自己能在人群中拥有位置。云堇编排的《神女劈观》把她的故事写成戏，但戏文里的神女只身战胜灾祸，现实中的申鹤还要面对活在人间的恐惧。\u003c/p\u003e\n\u003cp\u003e群玉阁升空之时，奥赛尔的妻子跋掣袭向璃月港。面对滔天巨浪，申鹤以寒冰阻住海啸；凝光与璃月众人也一同投入战斗。申鹤没有被要求回到孤绝的山里，也没有被当成传说中的工具。云堇在舞台上唱起她的故事，旅行者与同伴在台下迎她归来。璃月人的时代因而又多了一层意义：凡人与仙缘者可以并肩，而非互相退让。\u003c/p\u003e\n\u003cp\u003e海祇岛下方，旅行者进入与地表隔绝的渊下宫。这里没有真正的太阳，古人造出「大日御舆」照亮黑夜；控制光暗的机关也成为权力工具。被奉为「太阳之子」的儿童统治者，实际上遭大人操纵，长大后又被残酷地处死。曾救下此地居民的蛇神奥罗巴斯，后来带他们迁往海面，海祇岛的历史由此与地下古国相连。\u003c/p\u003e\n\u003cp\u003e渊下宫留下《日月前事》。书中声称，提瓦特极古老的历史涉及「原初之人」、其四个影子，以及后来降临的另一股力量；它与人们熟知的七神时代叙事并不相同。**此时它是一份古文献的记述，不等于旅行者已亲眼证实每个细节。**另有资料暗示，奥罗巴斯因接触这份禁忌历史而必须付出代价。它为何走向与雷神的战争，已不再像表面看来那样简单。\u003c/p\u003e\n\u003cp\u003e渊下宫的震撼在于：这里的人曾在无日之地造出光，也曾让光成为压迫。旅行者带走的不只是一册古书，还有对提瓦特起源的新疑问。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.4\"\u003e2.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Crane_Returns_on_the_Wind\"\u003e风起鹤归\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Enkanomiya\"\u003e渊下宫\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Before_Sun_and_Moon\"\u003e日月前事\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.5","major":2,"minor":5,"title":"无魔神任务：雷电将军的第二次抉择","chapter":"无主线","sections":[{"id":"v2.5-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 雷电将军传说任务第二幕「须臾百梦」在本版本推进了稻妻主线留下的问题。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e影走出一心净土，亲见稻妻人如何在失去之后仍选择向前。她终于意识到，自己把姐姐真珍视的「永恒」理解成了停滞。五百年前，真死于坎瑞亚灾厄；影的哀伤与对磨损的恐惧，使她创造了执行旧规则的将军人偶。如今影要改变方向，人偶却忠于她当初写下的理念，拒绝让步。\u003c/p\u003e\n\u003cp\u003e影与将军在意识空间中交战，时间在其中与外界流逝不同。她反复战斗，直到证明自己不再是那个只想保存过去的人。真留下的意识与神樱之种，在神秘的时间回环里与影重逢；影将种子种下，也才明白稻妻人早已生活在真留给她的守护之中。影随后结束锁国令，愿意亲自倾听国家的未来，而不是把永恒完全交给一具人偶。\u003c/p\u003e\n\u003cp\u003e同期「三界路飨祭」再次把旅行者带回渊下宫。侵蚀与深渊的力量威胁地下区域，旅行者借装置净化污染。渊下宫并非探索完古书便已经安全；人、龙蜥与异界力量之间的边界仍十分脆弱。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.5\"\u003e2.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Transient_Dreams\"\u003e须臾百梦\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.6","major":2,"minor":6,"title":"第二章第四幕：回响渊底的安魂曲","chapter":"第二章第四幕","sections":[{"id":"v2.6-s0","title":"同期世界支线：层岩巨渊","kind":"world","html":"\u003cp\u003e层岩巨渊深处，旅行者与戴因斯雷布再遇。他们追踪倒悬古城、黑色污泥与深渊教团的机关，发现大量丘丘人来到地下，不是为了进攻，而是为了在生命尽头寻一处避光的归宿。戴因斯雷布说明，坎瑞亚灾厄后的诅咒使许多人变成丘丘人，漫长岁月还会继续磨去他们残存的自我；另一些人则背负不死的诅咒。\u003c/p\u003e\n\u003cp\u003e深渊教团想利用地下装置「净化」诅咒。旅行者起初也盼有一条救赎之路，戴因斯雷布却警告：强行驱除诅咒可能把受难者剩余的生命一起毁掉。昔日坎瑞亚卫队的哈夫丹仍以残破身躯守护同胞；他与戴因斯雷布的相认，让「怪物」一词显得残酷而狭窄。最终，旅行者与戴因斯雷布阻止装置继续伤害受诅咒者，也没能替他们解开诅咒。\u003c/p\u003e\n\u003cp\u003e这一幕没有给出一个干净的胜利。旅行者知道血亲的阵营试图救坎瑞亚旧民，但方法会牺牲他们眼前的生命；戴因斯雷布阻止了灾难，却仍无法救回故国。双方都背着五百年的债。\u003c/p\u003e\n\u003cp\u003e矿工与志琼的调查揭开地下更古老的遗迹、悬浮的奇异晶石和侵蚀地脉的黑泥。旅行者借流明石净化道路。巨渊说明，深渊之力并非只存在于教团的仪式里，它也会渗入土地，让后来者面对前代灾变的余波。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.6\"\u003e2.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Requiem_of_the_Echoing_Depths\"\u003e回响渊底的安魂曲\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Chasm\"\u003e层岩巨渊\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.7","major":2,"minor":7,"title":"间章第二幕：危途疑踪","chapter":"间章第二幕","sections":[{"id":"v2.7-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e旅行者在层岩巨渊下方与夜兰、烟绯、荒泷一斗、久岐忍和魈相遇。众人跌入会扭曲道路与记忆的地下空间，出口反复消失，仿佛这座深渊要让每个人面对自己最不愿触碰的往事。魈追索的是五百年前曾在此战斗的夜叉浮舍；夜兰则寻找先辈留下的线索。\u003c/p\u003e\n\u003cp\u003e他们逐渐拼出灾厄时期的战场：坎瑞亚怪物从巨渊涌出，夜叉浮舍与璃月军士伯阳并肩封住缺口。浮舍早被业障与漫长征战夺去记忆，最后仍选择留下。那不是传奇里毫无痛苦的牺牲，而是一个几乎忘了自己的战士，对守护所作的最后回答。\u003c/p\u003e\n\u003cp\u003e众人借太威仪盘打开退路。魈一度耗尽力量，把生机留给同伴；钟离暗中出手，才使他也从巨渊归来。夜兰带走家族往事的答案，魈则终于能为浮舍和其他夜叉哀悼。旅行者看见，璃月的安稳由神、仙、军人与无名者共同换来。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.7\"\u003e2.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Perilous_Trail\"\u003e危途疑踪\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"2.8","major":2,"minor":8,"title":"无魔神任务：金苹果群岛的幻梦","chapter":"无主线","sections":[{"id":"v2.8-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 这段限时冒险是前往须弥前的过渡。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者与菲谢尔、莫娜、万叶、辛焱等人再赴金苹果群岛。岛屿受到愚人众装置影响，显出与同行者内心相连的幻境：万叶重走家门衰败与离乡之路，辛焱面对对音乐的坚持，菲谢尔直面理想自我与真实自我的距离，莫娜也要承认占星术无法免除人的选择。众人分别走过这些幻梦，装置危机得以平息。\u003c/p\u003e\n\u003cp\u003e这段故事的意义不在于改变七国格局，而在于让旅行者在一次次别人的心境里看见：记忆可以困住人，也可以使人有勇气走向下一程。旅途末尾，陌生的声音借意识向旅行者发出邀请；须弥近在前方，关于梦与智慧的新篇章即将开始。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/2.8\"\u003e2.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Summertime_Odyssey\"\u003e远海诗夏游纪\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.0","major":3,"minor":0,"title":"第三章第一至二幕：穿越烟帷与暗林；千朵玫瑰带来的黎明","chapter":"第三章第1至2幕","sections":[{"id":"v3.0-s0","title":"同期世界支线：森林书","kind":"world","html":"\u003cp\u003e旅行者踏入须弥雨林，首先闻到能令人失神的神秘熏香，并在昏迷中窥见与世界树相连的异象。巡林官提纳里与见习巡林员柯莱照料了他们。柯莱患有魔鳞病，身体上的鳞片提醒旅行者：须弥的「智慧」并未治愈每一个人。教令院让民众佩戴虚空终端，以神明赐予的系统获取知识；但须弥人似乎也因此不再自然做梦。\u003c/p\u003e\n\u003cp\u003e旅行者进入须弥城，盼见草神小吉祥草王纳西妲，却发现她虽是现任神明，长期不被教令院尊重。花神诞祭前，舞者妮露坚持为草神献舞。节日到了又结束，旅行者却一次次在同一个早晨醒来；熟悉的对话、错位的细节与不断积累的疲惫，证明他们被困在循环里。\u003c/p\u003e\n\u003cp\u003e纳西妲以「凯瑟琳」的身体与旅行者接触，帮助他们识破真相：这是由虚空系统抽取民众梦境、反复重演花神诞祭的实验。城市里的人以为自己醒着，实际在一个个被剥夺的梦中消耗。旅行者与妮露一同找到了这场梦的主人；妮露终于在梦中跳完献给草神的舞，循环瓦解。纳西妲救出了众人，却仍没有能力自由走出教令院施加的束缚。\u003c/p\u003e\n\u003cp\u003e兰那罗的故事把雨林的危机呈现为另一种语言。旅行者为救拉娜，走入精灵们的记忆与梦，认识侵蚀森林的「无留陀」。兰那罗会为了守护朋友而消耗记忆；他们的温柔并非不知痛苦，而是明知会遗忘，仍愿伸出手。雨林的枯败与人的病症尚未得到完整解释，但「世界的记忆」已成为须弥最重要的谜团。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.0\"\u003e3.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Aranyaka\"\u003e森林书\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.1","major":3,"minor":1,"title":"第三章第三至四幕：迷梦与空幻与欺骗；赤土之王与三朝圣者","chapter":"第三章第3至4幕","sections":[{"id":"v3.1-s0","title":"同期世界支线：黄金梦乡","kind":"world","html":"\u003cp\u003e花神诞祭的梦虽被打破，教令院的计划却没有结束。旅行者与艾尔海森发现，贤者们利用虚空终端操纵舆论、搜索知识，连许多人的判断都被系统牵引。愚人众执行官「博士」多托雷进入须弥，凭借更高层级的虚空权限压制旅行者，并逼迫纳西妲再次退回教令院的禁锢中。\u003c/p\u003e\n\u003cp\u003e线索把众人引向沙漠。赤王遗民长期相信，草神一系夺走了沙漠的繁荣；教令院也借这种隔阂，把被流放的学者与沙漠居民卷入自己的秘密计划。旅行者、艾尔海森、赛诺、迪希雅与坎蒂丝在阿如村并肩调查，逐渐发现失踪学者并未单纯遭人掳走，而与教令院正在酝酿的「造神」计划相连。\u003c/p\u003e\n\u003cp\u003e古遗迹中的记录动摇了沙漠流传的仇恨叙事：赤王引发的禁忌知识灾祸并非由草神制造，前代草神反而曾出手阻止灾难蔓延。赤王、花神与草神之间的过去，比教令院与沙漠民众口耳相传的故事复杂得多。各人暂且放下世代隔阂，决定救出纳西妲，并阻止贤者把须弥带进下一场浩劫。\u003c/p\u003e\n\u003cp\u003e旅行者随婕德、哲伯莱勒等人走进赤王遗迹。那些金色陵寝既保存失落技术，也埋着远古王权的骄傲与灾变。婕德的旅程把沙漠古史落到一个家庭的得失上：探索古国并非只为了寻找宏伟答案，还会逼活着的人承担代价。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.1\"\u003e3.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Golden_Slumber\"\u003e黄金梦乡\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.2","major":3,"minor":2,"title":"第三章第五幕：虚空鼓动，劫火高扬","chapter":"第三章第五幕","sections":[{"id":"v3.2-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e教令院要让散兵成为新的神明。贤者借花神诞祭等实验积累梦与知识，再以神之心驱动巨大的机械神躯；他们把民众的智慧当作造神的燃料，把仍在世的草神纳西妲当作可以丢弃的旧答案。\u003c/p\u003e\n\u003cp\u003e旅行者与艾尔海森、赛诺、迪希雅、妮露等人制订各司其职的救援。艾尔海森以被控制的假象潜入教令院，妮露把卫兵引离要地，赛诺追究贤者罪责。纳西妲终于走出净善宫。面对已登上机械神座的散兵，旅行者一次次败下阵来；纳西妲把战斗中的记忆化作可供学习的知识，让旅行者在不断修正中找到胜机，击败新生之神。\u003c/p\u003e\n\u003cp\u003e真正的危机还在世界树中。大慈树王的残留意识告诉纳西妲，五百年前她以自身力量抵御禁忌知识，却也被污染。只要世界仍记得她，污染便不能完全消散。纳西妲必须从世界树中抹去大慈树王的存在；两位草神在最后的相拥中告别。世界随之重写记忆：人们忘记曾有另一位草神，魔鳞病与死域的根本病灶得到清除。\u003cstrong\u003e旅行者作为来自世界之外的人，仍记得那位被遗忘的神。\u003c/strong\u003e\u003c/p\u003e\n\u003cp\u003e博士随后与纳西妲谈判，以销毁自己的其他「切片」及一条关于提瓦特天空的情报，换取两枚神之心。纳西妲又告诉旅行者：世界树能记录失散血亲，却没有记录旅行者自身；血亲在提瓦特的身份，似乎与他们想象中的「同为异乡人」不同。她无法替旅行者解答所有问题，但须弥一役已把「世界会记住什么、遗忘什么」变成寻找血亲的核心线索。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.2\"\u003e3.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.3","major":3,"minor":3,"title":"间章第三幕：倾落伽蓝","chapter":"间章第三幕","sections":[{"id":"v3.3-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e散兵战败后留在须弥。旅行者陪他进入世界树，他在那里读到自己作为雷神造物、被遗弃者与愚人众执行官的过去，也读到踏鞴砂悲剧背后的欺骗。他以为自己只给他人带来不幸，便试图从世界树里抹去「散兵」的存在，好让受害者获得另一种人生。\u003c/p\u003e\n\u003cp\u003e世界的记忆确实改写了：人们不再记得散兵，相关故事也找到了新的解释。然而旅行者亲自查证后发现，已经发生的死亡并未倒转。抹掉名字能改变人们如何叙述过去，不能让过去未曾发生。一个失去记忆的青年游荡在须弥，纳西妲则把散兵的往事藏成寓言，让他有机会重新面对自己。\u003c/p\u003e\n\u003cp\u003e旅行者把真相还给青年。他选择取回记忆，承认过去所犯的事，也不再任由旧身份替自己决定未来。纳西妲收留他，旅行者为他起了新名字——流浪者。此刻的他不因赎罪便自动获得宽恕，却终于能以自己的意志承担后果。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.3\"\u003e3.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Inversion_of_Genesis\"\u003e倾落伽蓝\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.4","major":3,"minor":4,"title":"无魔神任务：比勒琪丝的哀歌","chapter":"无主线","sections":[{"id":"v3.4-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本延续沙漠世界任务。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者再见婕德，随她回到塔尼特部族，深入风暴覆盖的千壑沙地，寻找传说中的永恒绿洲。传说里的花神遗迹并不能替活着的人解决权力与猜忌；婕德在部族的谋划中一次次失去依靠，最终不得不与曾以为是家的人诀别。\u003c/p\u003e\n\u003cp\u003e永恒绿洲凝住了极古老的美与哀伤。赤王、花神与前代草神的交往，在壁画和记述里比单一国度的传说更有人性；但再辉煌的旧梦，也救不了当下被利用的人。婕德走出沙海时，不再是那个只需追随父亲的少女。她的命运让旅行者看见，所谓「探索古文明」从来会触及仍活着的后人。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.4\"\u003e3.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Dirge_of_Bilqis\"\u003e比勒琪丝的哀歌\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.5","major":3,"minor":5,"title":"第三章第六幕：卡利贝尔","chapter":"第三章第六幕","sections":[{"id":"v3.5-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e戴因斯雷布在须弥再度现身。凯亚偶然谈及自己的姓氏——亚尔伯里奇——使坎瑞亚的旧影逼近。旅行者随后陷入一段与血亲的记忆相连的经历，见到坎瑞亚贵族克洛达尔·亚尔伯里奇和他的儿子卡利贝尔。父亲是不死的受诅咒者；儿子已变成丘丘人，仍被父亲珍爱。克洛达尔不肯接受儿子只能慢慢失去自我，四处求取能解除诅咒的方法。\u003c/p\u003e\n\u003cp\u003e他在神秘晶体前听见自称「罪人」的声音。声音带来超出常理的力量与希望，也诱使绝望中的父亲把救赎寄托在未知存在身上。卡利贝尔短暂显出变化，却没有在旅行者眼前迎来明白无误的结局。克洛达尔后来与深渊教团的起源联系在一起。旅行者醒来后才意识到，自己所经历的并非普通的当下调查，而是血亲曾走过的往事。\u003c/p\u003e\n\u003cp\u003e坎瑞亚的灾难至此有了父与子的面孔。深渊教团的诞生不只是一个反神口号，也来自活生生的人在诅咒面前不肯放手的悲痛；但「罪人」究竟是什么，仍无人能给出可靠答案。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.5\"\u003e3.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Caribert\"\u003e卡利贝尔\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.6","major":3,"minor":6,"title":"无魔神任务：善恶的赫瓦雷纳","chapter":"无主线","sections":[{"id":"v3.6-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 沙漠北境的世界任务延续了坎瑞亚灾厄留下的地理伤痕。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者与花灵斯露莎走进荼泥黑渊。五百年前，灾厄从此处撕开大地，深渊力量威胁须弥；树、花灵与奉献自身的守护者合力封住裂隙。如今封印松动，旅行者帮助斯露莎完成净化，也读到那些为后人保住土地者留下的记录。\u003c/p\u003e\n\u003cp\u003e这段支线将宏大的「坎瑞亚灾厄」落到一块具体的地形：地面上的巨坑、仍在涌动的污秽、延续五百年的守望，都说明那场灾变远未结束。斯露莎在旅途中学会，守护并非只模仿前人的牺牲，也包括与同行者共同活下去。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.6\"\u003e3.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Khvarena_of_Good_and_Evil\"\u003e善恶的赫瓦雷纳\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.7","major":3,"minor":7,"title":"无","chapter":"无主线","sections":[{"id":"v3.7-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e本版本没有新增魔神任务，也没有必须放进寻找血亲、七神或提瓦特古史主线的世界任务。旅行者参与七圣召唤赛事，结识来自各地的人，也与来自枫丹的记者夏洛蒂相遇；这更像去往下一个国度前的短暂停驻。\u003c/p\u003e\n\u003cp\u003e接下来的主要目标仍是枫丹。到此刻，旅行者只知道那里是水神统治、以审判闻名的国度，不应提前知道那里的真相。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.7\"\u003e3.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"3.8","major":3,"minor":8,"title":"无魔神任务：琉形蜃境","chapter":"无主线","sections":[{"id":"v3.8-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本的限时秘境是须弥篇后的尾声。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者与可莉等人来到琉形蜃境，见到由纯水精灵伊迪娅守护的水域幻境。这里收留了不少暂离现实的人，愿望与回忆被做成可供游历的景象。伊迪娅并非要永远把客人关在安全的梦里；当误会解开，众人仍要回到各自的生活。\u003c/p\u003e\n\u003cp\u003e枫丹的水、纯水精灵与「现实能否容纳人的愿望」在这场冒险里提前露面。但旅行者对枫丹的神明和预言尚无答案。离开蜃境，新的国度正等待他们亲自走入。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/3.8\"\u003e3.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Veluriyam_Mirage\"\u003e琉形蜃境\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.0","major":4,"minor":0,"title":"第四章第一至二幕：白露与黑潮的序诗；仿若无因飘落的轻雨","chapter":"第四章第1至2幕","sections":[{"id":"v4.0-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e旅行者来到枫丹，首先看到的是一座把审判当作公共生活中心的国度。水神芙宁娜热爱舞台与喝彩，最高审判官那维莱特则以沉静的姿态主持法庭。传说里的预言在街头流传：海水终将上涨，所有枫丹人会溶解，只剩水神在神座上哭泣。\u003c/p\u003e\n\u003cp\u003e魔术师林尼与妹妹琳妮特接待旅行者。林尼的公开表演发生命案，一名观众也离奇失踪；在法庭上，林尼被指控借魔术杀人。旅行者为他辩护，逐步揭出有人利用舞台机关与「原始胎海之水」犯罪。审判落幕，旅行者又得知林尼兄妹属于愚人众的「壁炉之家」。这份隐瞒伤了彼此初建的信任，但他们并非审判中的真凶。\u003c/p\u003e\n\u003cp\u003e随后，旅行者与刺玫会的娜维娅追查多年女性连环失踪案。娜维娅的父亲卡雷斯当年背负罪名而死，她坚信父亲并非凶手。线索最终指向商人瓦谢：他用原始胎海之水使受害者溶解，妄想找回早已消失的爱人。被害者的意识在水中发声，审判让他的罪行昭于人前，也还了卡雷斯清白。枫丹人遇到胎海之水会溶解的事实，令预言忽然有了可怕的现实根基。\u003c/p\u003e\n\u003cp\u003e那维莱特在案件中显出远超普通人的感知与力量，却未把全部身份说明。旅行者在枫丹才刚站稳脚跟，便发现这里的真相经常要先经过一场表演，再经一场审判，最后才能被人相信。\u003c/p\u003e\n\u003cp\u003e安眠处与厄里那斯一带的支线，开始显露「水仙十字结社」的踪迹：一群曾想研究枫丹预言、灵魂与水的旧日人物，留下孤儿院、实验与无法安息的造物。这条线暂未在 4.0 讲完。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.0\"\u003e4.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.1","major":4,"minor":1,"title":"第四章第三至四幕：向深水中的晨星；谕示胎动的终焉之刻","chapter":"第四章第3至4幕","sections":[{"id":"v4.1-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e愚人众执行官公子在枫丹审判中遭「谕示裁定枢机」判有罪，随后从梅洛彼得堡失踪。旅行者主动进入这座海下监狱，寻找他的去向。那里的囚犯有自己的经济与秩序；典狱长莱欧斯利表面上管理牢狱，暗中却为预言准备一艘巨大方舟。监狱最深处封着通往原始胎海的危险缺口。\u003c/p\u003e\n\u003cp\u003e旅行者调查时，胎海之水突然上涌。莱欧斯利与克洛琳德争取时间，那维莱特亲自赶到，以力量暂时压住封印。比任何法庭辩词都更明白的事实摆在眼前：枫丹的灾难并非传言。公子的失踪则似与胎海深处某种庞然生命有关，旅行者尚无法把他带回。\u003c/p\u003e\n\u003cp\u003e与此同时，愚人众执行官「仆人」阿蕾奇诺与芙宁娜会面。她想确认水神是否真有阻止预言的方案，也关心枫丹孩子的生死；芙宁娜却总用舞台上的姿态遮掩焦虑，无法给出令众人安心的解释。旅行者与那维莱特不得不思考：若灾难已逼近，水神究竟知道多少，又为什么独自承受而不肯说出？\u003c/p\u003e\n\u003cp\u003e梅洛彼得堡里的「未完成的喜剧」继续牵出水仙十字结社旧人的遗迹。枫丹把不合群者送入海底，也把许多历史秘密沉在海底；两者渐渐交会。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.1\"\u003e4.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.2","major":4,"minor":2,"title":"第四章第五幕：罪人舞步旋","chapter":"第四章第五幕","sections":[{"id":"v4.2-s0","title":"重要世界支线：水仙十字结社的终局","kind":"world","html":"\u003cp\u003e预言逼近应验。旅行者与枫丹诸人设局，让芙宁娜置身于一场真正的审判。他们并非只要揭穿一名演员；他们需要找出能够阻止枫丹人溶解的办法。审判中，芙宁娜既无法证明自己拥有神力，也拒绝说出五百年来守着的秘密。陪她度过漫长岁月的孤独与恐惧终于显形：她只是人，却必须每天扮演神，哪怕一瞬间的失误都可能使整个计划前功尽弃。\u003c/p\u003e\n\u003cp\u003e那维莱特在「谕示裁定枢机」深处见到真正的水神芙卡洛斯。前代水神厄歌莉娅曾以原始胎海之水让纯水精灵成为人；这在天理看来是「原罪」，预言因此悬在枫丹头顶。芙卡洛斯把自身的神性藏入裁定枢机，让人性的一面——芙宁娜——在世人面前演完五百年的戏。她收集律偿混能，最终用它处决自己，毁去水神神座，把水元素的完整权能还给水龙王那维莱特。\u003c/p\u003e\n\u003cp\u003e预言仍以海水淹没枫丹的形式到来。吞星之鲸从胎海现身，公子曾在水下独自与它缠斗；旅行者和那维莱特最终将它击退。得到完整权能的那维莱特宽恕了枫丹人的「原罪」，使他们真正成为不会因胎海之水而溶解的人。水退后，预言表面上应验，枫丹人却活了下来。\u003c/p\u003e\n\u003cp\u003e芙宁娜终于卸下水神的角色。她没有从一开始就在欺骗所有人以求喝彩；她把恐惧独自压了五百年，才使这个结局成为可能。那维莱特接过守护枫丹的责任，阿蕾奇诺得到水神之心。旅行者离开法庭时，记住的不只是芙卡洛斯精密的计谋，也是一个凡人忍住不能倾诉的漫长一生。\u003c/p\u003e\n\u003cp\u003e「水仙的追迹」将安、玛丽安、雅各布与雷内等人留下的线索汇合。雷内曾推演枫丹预言，想以新的集体意识替人们绕开灭亡，却把个体生命当成可合并的材料。旅行者阻止其方案。它与芙卡洛斯的计划形成尖锐对照：两者都想救人，方法却决定了被救者是否还能以自己活着。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.2\"\u003e4.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Archon_Quest\"\u003e魔神任务目录\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/In_the_Wake_of_Narcissus\"\u003e水仙的追迹\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.3","major":4,"minor":3,"title":"无","chapter":"无主线","sections":[{"id":"v4.3-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e本版本没有新增魔神任务，也没有改变旅行者对血亲、七神或提瓦特古史认识的必要世界任务。枫丹灾厄后的生活继续，旅行者参与「蔷薇与铳枪」的电影拍摄，见证众人重拾节庆与创作。对刚从预言中幸存的国度而言，日常能重新开始本身就有重量。\u003c/p\u003e\n\u003cp\u003e此时芙宁娜作为普通人学习重新生活；她不需要再向每一个观众证明自己是神。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.3\"\u003e4.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.4","major":4,"minor":4,"title":"无魔神任务：沉玉谷的古老契约","chapter":"无主线","sections":[{"id":"v4.4-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本开放的沉玉谷，补上璃月山水与仙人关系的一页。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者在沉玉谷结识与山川灵脉相连的仙灵，修复被旧日纷争破坏的水土。此地的茶、河流与祭仪，来自人与仙人长期相处的契约；守护并非一场胜仗就能完成，而要一代代人维护水路、记得节令，也容许旧友放下怨怼。\u003c/p\u003e\n\u003cp\u003e沉玉谷支线不改变枫丹篇的结局，却让璃月「人治」的含义更宽：人们接手的不止港口的政务，还有深山中的生态与记忆。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.4\"\u003e4.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Chenyu%27s_Blessings_of_Sunken_Jade\"\u003e沉玉祝珑\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.5","major":4,"minor":5,"title":"无","chapter":"无主线","sections":[{"id":"v4.5-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e本版本没有新增魔神任务，也没有必须收入血亲与提瓦特古史脉络的世界任务。旅行者在枫丹继续与友人往来；关于坎瑞亚、深渊教团和下一段国度旅程的悬念，仍留在此前章节的状态。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.5\"\u003e4.5 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.6","major":4,"minor":6,"title":"无魔神任务：壁炉之家与雷穆利亚","chapter":"无主线","sections":[{"id":"v4.6-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本两条重要旁线分别指向愚人众的内部与枫丹更古老的王国。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e阿蕾奇诺的传说任务让旅行者走近「壁炉之家」。孩子们称她为「父亲」，但这个家既能庇护失去归处的孩子，也要求他们为愚人众承担危险任务。上一任院长库嘉维娜以残酷竞争操控孩子；阿蕾奇诺曾亲手结束她的统治，也背负挚友克雷薇之死。她如今对孩子们严厉，甚至让他们害怕，却并不愿让往日的残忍重新成为规则。她身上的赤月与火焰力量，则暗示其身世连着坎瑞亚更古老的血脉；本版本尚未解释完整。\u003c/p\u003e\n\u003cp\u003e佩特莉可镇与海底遗迹引出雷穆利亚。古王雷穆斯曾想以宏伟的乐章和精密秩序拯救自己的臣民，最后却令一个王国沉没。旅行者在遗迹中协助仍被旧日旋律束缚的生命，见到另一种「为所有人安排好未来」如何压碎个人意愿。它与枫丹预言的主题遥相呼应：救赎若剥夺被救者的选择，便容易变成新的牢笼。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.6\"\u003e4.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Canticles_of_Harmony\"\u003e谐律上的咏叙诗\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.7","major":4,"minor":7,"title":"第四章第六幕：睡前故事","chapter":"第四章第六幕","sections":[{"id":"v4.7-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e戴因斯雷布与旅行者继续追查深渊教团。熟悉的村庄和失踪者，把他们引回克洛达尔与卡利贝尔的往事。卡利贝尔当年并未简单地从故事里消失；他的意识以特殊方式延续，能够借他人的记忆与梦现身。他想让旅行者理解父亲追求「命运的织机」的理由，也想让命运不再只由天上书写。\u003c/p\u003e\n\u003cp\u003e旅行者终于与血亲有了一次可以交谈的相会。两人仍彼此牵挂，却对现阶段应采取的道路无法达成一致。血亲相信自己已看见提瓦特深处的真相，旅行者则不愿因尚未亲眼求证就加入深渊教团。会面短暂如梦；旅行者留住了一幅两人并肩的影像，却仍未能把血亲带回。\u003c/p\u003e\n\u003cp\u003e深渊教团也取得「第一台耕地机」的关键部件，使命运的织机计划向完成迈进。与此同时，旅行者得知坎瑞亚有五位曾触及深渊力量的「罪人」；他们的选择与五百年前故国的命运息息相关。戴因斯雷布尤其难以平静，因为其中一人是他的兄弟。此刻这些名字是新线索，不是已经讲完的答案。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.7\"\u003e4.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Bedtime_Story\"\u003e睡前故事\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"4.8","major":4,"minor":8,"title":"无魔神任务：希穆兰卡","chapter":"无主线","sections":[{"id":"v4.8-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 本版本的夏日限时剧情是走向纳塔前的寓言。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者进入由童话、绘本和魔法构成的希穆兰卡。众人一度以为必须照着故事书里的预言扮演英雄或恶龙，后来发现，写好的角色并不能决定生命的价值。一个被称作「杜林」的小龙渴望被接纳；它与雪山巨龙的名字相同，却应先作为眼前这个会害怕、会选择的生命被看见。旅行者与伙伴改写了童话的结局，也把小龙带离原本的孤独。\u003c/p\u003e\n\u003cp\u003e这场冒险没有提前讲明纳塔的真相。它只在新旅程前留下一句温柔的提醒：即使故事给某人写好了可怕的称谓，也不能替他决定他将成为谁。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/4.8\"\u003e4.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Simulanka\"\u003e希穆兰卡\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.0","major":5,"minor":0,"title":"第五章第一至二幕：荣花与炎日之途；黑石湮落白石下","chapter":"第五章第1至2幕","sections":[{"id":"v5.0-s0","title":"同期世界线索","kind":"world","html":"\u003cp\u003e旅行者从枫丹入纳塔，最先认识的是回声之子的少女卡齐娜。她几次在盛大的「归火圣夜巡礼」中失利，仍不愿放弃成为守卫家园的战士。纳塔的六个部族与龙伙伴共同生活，拥有「古名」的战士会在巡礼后深入夜神之国，与深渊作战；只要队伍得胜、古名仍被铭记，战死者便有机会借还魂诗复活。这里的战争不是传说，而是每一代人都要参加的现实。\u003c/p\u003e\n\u003cp\u003e卡齐娜终于赢得资格，却在随后的夜巡中阵亡。众人准备以还魂诗迎她归来，火神玛薇卡却找不到她的古名。深渊侵蚀了夜神之国，正在破坏纳塔赖以抵抗它的规则。玛薇卡暂停巡礼，派旅行者、玛拉妮、恰斯卡等人寻找卡齐娜。旅行者能净化一部分深渊力量，令本不可能的救援有了一线希望。\u003c/p\u003e\n\u003cp\u003e愚人众首席执行官「队长」也来到纳塔，认为玛薇卡的计划过于危险，试图夺取火神之心并接手抵抗深渊的方式。二人在圣火前交锋；玛薇卡击退队长，却也必须耗损自己的力量维系圣火。旅行者与伙伴进入夜神之国，把卡齐娜带回。胜利让人们重新唱起还魂诗，同时证明深渊已经摸到纳塔最深处的生命之脉。\u003c/p\u003e\n\u003cp\u003e玛薇卡告诉旅行者，自己的计划需要来自六部族的英雄，还需要一个能在深渊里站立的外乡人。旅行者暂时不能从纳塔神像取得火元素，似乎也在等待那场尚未到来的决战。\u003c/p\u003e\n\u003cp\u003e纳塔的「古名」记录英雄事迹，夜神之国承担近似地脉的记忆功能。人能否复活，取决于名字、记忆与集体歌唱是否仍能连在一起；深渊侵蚀的不只是肉体，还会切断这种联系。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.0\"\u003e5.0 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Flowers_Resplendent_on_the_Sun-Scorched_Sojourn\"\u003e荣花与炎日之途\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Black_Stone_Under_a_White_Stone\"\u003e黑石湮落白石下\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.1","major":5,"minor":1,"title":"第五章第三至四幕：镜与谜烟的彼方；命定将焚的虹光","chapter":"第五章第3至4幕","sections":[{"id":"v5.1-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e旅行者协助希诺宁寻找为外乡人锻造古名的办法，又与茜特菈莉追查夜魂部族青年欧洛伦为何救走队长。队长并非只为愚人众的命令而来。他经历过五百年前的坎瑞亚灾厄，见过深渊如何吞掉一个国家，因而不肯把纳塔的存亡押在玛薇卡尚未完成的计划上。他试图借古代装置重塑夜神之国的地脉，代价却可能是守护这片土地的古老存在。\u003c/p\u003e\n\u003cp\u003e欧洛伦在装置危机中抗拒侵入自己灵魂的旧日亡魂，继承「奉献」的古名。夜神之国的主人向众人现身：她曾属于早于如今仙灵形态的「天使」一族，长久维系纳塔特殊的记忆网络。玛薇卡拒绝为眼前安全把她耗尽。队长虽仍不完全认同，也决定先与纳塔结盟，共抗逼近的深渊。\u003c/p\u003e\n\u003cp\u003e灾难很快真正降临。深渊同时袭击多个部族、道路和村落，旅行者随各地求援不断奔走。有人赶上救援，有人来不及；恰斯卡失去妹妹，纳塔人也不得不统计一座座村落的死伤。玛薇卡与六英雄汇聚力量，向蔓延的黑暗挥出足以撕开天空的一击，暂时止住全面入侵。天空裂隙中显露的异象，让「提瓦特的天空」也成为无法忽视的疑问。\u003c/p\u003e\n\u003cp\u003e纳塔赢下的是喘息时间。玛薇卡若要调用主宰死亡的力量彻底结束战争，自己也将被索取代价。旅人与盟友知道了这个风险，仍选择为下一次、也是最后一次深入夜神之国做准备。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.1\"\u003e5.1 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Beyond_the_Smoke_and_Mirrors\"\u003e镜与谜烟的彼方\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Rainbow_Destined_to_Burn\"\u003e命定将焚的虹光\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.2","major":5,"minor":2,"title":"第五章间幕：万火归一","chapter":"第五章间幕","sections":[{"id":"v5.2-s0","title":"同期世界支线","kind":"world","html":"\u003cp\u003e大战之后，花羽会受创尤重。旅行者与伊安珊探望幸存战士：有人在噩梦中仍看见已死的龙伙伴，有人把亲友认作深渊怪物。伤口并非只在战场上；纳塔要恢复，还须认真照顾被战争改写心灵的人。队长提供曾由部下研究的药物，救下一名受深渊侵蚀严重的战士，也再次说明自己与纳塔五百年的交情。\u003c/p\u003e\n\u003cp\u003e希诺宁仍在为旅行者锻造古名。朋友们聚在「巡礼之证」前，讲述旅行者在纳塔的所作所为；玛拉妮、卡齐娜、基尼奇、茜特菈莉、欧洛伦与恰斯卡的见证，将一个外乡人的事迹写进夜神之国可以接纳的历史里。古名还未完成，但这份共同记忆已经让最后的决战有了根基。\u003c/p\u003e\n\u003cp\u003e奥奇卡纳塔遗迹延续纳塔人与古龙文明的冲突史。探索者逐渐看见，今日的纳塔并非只有「人与深渊」的二元战线；龙的王国、秘密源装置和古老统治者，也留在土地深处。此时不应把这些碎片当作已拼完的整幅图。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.2\"\u003e5.2 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/All_Fires_Fuel_the_Flame\"\u003e万火归一\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.3","major":5,"minor":3,"title":"第五章第五幕：炽烈的还魂诗","chapter":"第五章第五幕","sections":[{"id":"v5.3-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e决战前夜，纳塔人设宴送行。玛薇卡并非没有恐惧；她想念五百年前的家人，也知道自己的选择可能使她看不到和平后的国家。希诺宁终于铸成旅行者的古名 \u003cstrong\u003e「图玛伊尼」——希望\u003c/strong\u003e。当众人把旅行者在纳塔的事迹唱进历史，这位外乡人终于有资格与火神一同深入夜神之国。\u003c/p\u003e\n\u003cp\u003e玛薇卡寻找深渊的核心，旅行者沿另一条路前进。途中，牺牲者的灵魂一次次帮助他们：逝去的友人、部族战士与古代英雄，没有因为死去便从纳塔的守护中被抹去。夜神之国的主人赐予旅行者火元素之力。两人最终汇合，击败深渊的强大化身，扑灭其对纳塔地脉的侵蚀。纳塔赢得了不必世世代代以深渊战争为宿命的未来。\u003c/p\u003e\n\u003cp\u003e胜利的欢呼之后，主宰死亡的洛诺瓦仍要收取玛薇卡使用其力量的代价。队长站了出来。他作为坎瑞亚的长生受诅咒者，五百年来把同袍的记忆与亡魂背在身上，早已盼他们能安息。他与夜神之国的主人合一，替玛薇卡承受命定之死，也为那些无家可归的灵魂找到归处。玛薇卡活下来，却必须带着对这位对手兼盟友的敬意继续统治。\u003c/p\u003e\n\u003cp\u003e纳塔人为死者立碑，也为活着的人开路。旅行者从玛薇卡那里得知，博士在至冬边境的挪德卡莱研究天空碎片与古月遗物；冰之国近在前方。队长未完成夺取火神之心的任务，而他最终选择的，是把纳塔的未来留给纳塔人。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Incandescent_Ode_of_Resurrection\"\u003e炽烈的还魂诗任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.3\"\u003e5.3 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.4","major":5,"minor":4,"title":"无","chapter":"无主线","sections":[{"id":"v5.4-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e本版本没有新增魔神任务。旅行者仍在纳塔大战之后的世界行走，也参与稻妻的节庆与友人故事；这一版没有需要先于后续主线交代的血亲、深渊或七神新结论。\u003c/p\u003e\n\u003cp\u003e纳塔篇的已知状态保持不变：深渊的全面战争暂告结束，队长与亡魂安息，博士在挪德卡莱的动向仍是下一步线索。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.4\"\u003e5.4 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.5","major":5,"minor":5,"title":"无魔神任务：古圣山的余烬","chapter":"无主线","sections":[{"id":"v5.5-s0","title":"本版纪事","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e\u003cstrong\u003e主线：无。\u003c/strong\u003e 纳塔新开放的沃陆之邦与古圣山，把故事目光重新投向古龙与早期人类的历史。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者循遗迹与古龙伙伴的足迹深入圣山。岩壁、装置和残存记录讲述更古老的纳塔：龙曾建立高度发达的文明，人类后来在战争与联盟中取得今日的生存空间。火、源火与秘密源技术既能守护生命，也曾被统治者用来塑造服从。如今各部族竞赛的热闹，与山下仍在沉睡的旧日王权形成鲜明反差。\u003c/p\u003e\n\u003cp\u003e此版本的世界任务提供的是纳塔远古史的碎片，不改写 5.3 对深渊战争的结局。对旅行者而言，它提醒他们：即使一场千年战争结束，土地的历史也不会跟着结束。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.5\"\u003e5.5 版本新增地区与世界任务\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.6","major":5,"minor":6,"title":"间章第四幕：悖理","chapter":"间章第四幕","sections":[{"id":"v5.6-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e旅行者回到蒙德过风花节，却发现城里有人行为反常，阿贝多又被控杀人。审判的证人与证据像是指向他，旅行者却记得雪山曾有与他相同容貌的造物。骑士团借审判诱出潜伏者，揭露杜林遗骸中滋生的生命会模仿人、吞噬人，并把怀疑引向阿贝多。怪物向蒙德发动袭击，骑士团与城中友人合力守住城门。\u003c/p\u003e\n\u003cp\u003e更大的危险是龙脊雪山的杜林将要复苏。阿贝多向魔女会寻求炼金材料，准备杀死被恶意侵蚀的旧龙躯，再以来自童话世界的小杜林为核心，让一个愿意善待人的新生命继承「杜林」之名。温迪、艾莉丝等人帮助完成仪式。小杜林成为人形，旧龙的威胁终被化解；他的意义并非替一条龙洗去过去，而是证明一个生命不必被创造者或同名者的罪预先定型。\u003c/p\u003e\n\u003cp\u003e阿贝多也透露更骇人的消息：创造他的莱茵多特与被称作「生命之执政」的纳贝里士发生了融合。旅行者已经知道坎瑞亚的五位罪人与古国灾厄相关，如今又看见其中一人的手伸向比七神更古老的层级。这仍只是故事新揭开的一角。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Paralogism\"\u003e悖理任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.6\"\u003e5.6 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.7","major":5,"minor":7,"title":"第五章第六幕：你存在的时空","chapter":"第五章第六幕","sections":[{"id":"v5.7-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e旅行者在纳塔捡到一把熟悉的钥匙：它属于双子曾乘坐的星间航行器，另一把一直由旅行者自己保管。钥匙把他们引向名叫迪蕾狄丝的少女。她自称奉命寻找能阻止末日的「救世主」，却似乎来自与旅行者不同的时间；她看得到的怪物，旁人未必看得到。\u003c/p\u003e\n\u003cp\u003e深渊教团同时袭击纳塔各部族。戴因斯雷布前来追击，两人发现攻势像是一场佯动。真正的行动由旅行者的血亲完成：借「命运的织机」重织坎瑞亚的地脉记忆，把故国保存在一幅新的世界图谱中。他们尚未把这个世界真正安置下来，但已取得与天上力量对话的筹码。夜神之国的主人允许短暂试验，以确保纳塔不会遭受直接伤害。\u003c/p\u003e\n\u003cp\u003e迪蕾狄丝与双子的旧日选择发生联系，时间的回环也使旅行者再次看见：血亲之所以走向坎瑞亚，并非只因一句反抗神明的宣言。两人面对面时，仍无法同行；血亲希望下一次相见能在其新世界里。戴因斯雷布阻止教团眼前的攻击，却未能阻止织机前进一步。旅行者的方向因此更清晰：继续亲自看清血亲想建造的世界，和它将要求别人付出的代价。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Space_and_Time_for_You\"\u003e你存在的时空任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.7\"\u003e5.7 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"5.8","major":5,"minor":8,"title":"空月之歌·序奏：归途","chapter":"空月之歌序奏","sections":[{"id":"v5.8-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e纳塔海边出现一名失忆的机械少女。她记得要找到旅行者与派蒙，却记不起自己为何而来；来自挪德卡莱的商队叫她伊涅芙。她的身体混合了枫丹机关、纳塔秘密源技术与其他地区的材料，而她护送的密匣，似乎专为旅行者准备。\u003c/p\u003e\n\u003cp\u003e伊涅芙在纳塔古龙遗迹中受到旧日意识争夺。旅行者与恰斯卡、希诺宁、茜特菈莉等人帮助她辨明：即便核心曾属于古龙的统治者，她也有权选择作为现在的伊涅芙活下去。愚人众同样追索遗迹技术，另一支与队长不同的力量已先一步渗向纳塔边境。\u003c/p\u003e\n\u003cp\u003e密匣最终打开，是西风骑士团大团长法尔伽的信。他在挪德卡莱，提醒旅行者那里聚集愚人众、深渊教团与彼此紧张的地方势力，并约他们在当地见面。另一边的消息提到，博士试图研究「古月」残遗，甚至要把月亮拖向地面。旅行者离开纳塔之前，已经知道下一站不只是去至冬的路，而是众多旧势力正围绕月之力量交汇的地方。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Journey_Home\"\u003e归途任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/5.8\"\u003e5.8 版本内容\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.0","major":6,"minor":0,"title":"空月之歌第一、二幕：雪浪与苍林之舞；尘与灯的挽歌","chapter":"空月之歌第1至2幕","sections":[{"id":"v6.0-s0","title":"第一幕：雪浪与苍林之舞","kind":"chapter","html":"\u003cblockquote\u003e\n\u003cp\u003e本篇止于 6.0。挪德卡莱与月亮的谜团，将随当地人的见闻逐步显现。\u003c/p\u003e\n\u003c/blockquote\u003e\n\u003cp\u003e旅行者与派蒙带着伊涅芙来到挪德卡莱的那夏镇。他们寻访失散已久的星间飞船，也想找到西风骑士团大团长法尔伽。这里并非至冬王廷，却有愚人众、商会、执灯人和信奉月神的霜月之子彼此角力。空气中流动的「月矩力」使旅行者感到熟悉，仿佛与双子最初降落于此的往事有关。\u003c/p\u003e\n\u003cp\u003e霜月之子的菈乌玛讲起古老的三月传说，也带旅行者走近隐居银月之庭的哥伦比娅。她曾是愚人众的「少女」，如今已脱离他们，仍被月光与故乡的渴望牵引。爱诺、菲林斯和愚人众执行官「木偶」桑多涅各自追索月之遗物；当名为「月髓」的东西现身，几方同盟随时可能散开。菈乌玛坦言族人所受的苦难，以及她的血为何与月髓有关；旅行者因此暂把月髓藏入自己体内，避免它立即落入任何一方手中。\u003c/p\u003e\n\u003cp\u003e月下，旅行者一度看见与血亲并肩行动的身影。重逢的希望很快化为陷阱：那是「狂猎」借熟悉面容作出的拟态。此地的敌人懂得把人的思念变成武器，旅行者必须先弄清它们从何而来。\u003c/p\u003e\n"},{"id":"v6.0-s1","title":"第二幕：尘与灯的挽歌","kind":"chapter","html":"\u003cp\u003e线索把众人引向坎瑞亚旧灾。月髓被认为是已毁之月「艾莉亚」的残骸；追逐它的狂猎则与坎瑞亚五位「罪人」之一雷利尔有关。雷利尔能以他人形貌现身，搜集散落的自身遗骸，试图恢复失去的肉身。守灯人菲林斯也承认自己的来历异于常人；他选择帮助活着的人，而灯中封存着雷利尔心脏的一片碎屑。\u003c/p\u003e\n\u003cp\u003e雷利尔没有只在暗处追猎。他诱导爱诺的月矩力大炮向自己开火，反借那股受污染的力量重铸躯体。桑多涅的干预未能拦住他，众人陷入险境，哥伦比娅以霜月之力救下同伴。敌人仍未被消灭；法尔伽循踪追去。旅行者此时明白，挪德卡莱的月之争夺并不是孤立的地方传说：古月、坎瑞亚灾厄与血亲的旧路，正在同一片天空下重新交会。\u003c/p\u003e\n"},{"id":"v6.0-s2","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e旅行者的飞船究竟落在何处？哥伦比娅为何与月髓相连？雷利尔要用恢复的身体做什么？法尔伽能否追上他？这些答案仍在前方。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Dance_of_Snowy_Tides_and_Hoarfrost_Groves\"\u003e第一幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Elegy_of_Dust_and_Lamplight\"\u003e第二幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E4%B9%8B%E6%AD%8C\"\u003e空月之歌中文幕名与任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.1","major":6,"minor":1,"title":"空月之歌第三、四幕：不存在的国土；回望湮灭的月光","chapter":"空月之歌第3至4幕","sections":[{"id":"v6.1-s0","title":"第三幕：不存在的国土","kind":"chapter","html":"\u003cp\u003e雷利尔重获部分身体后，矛头指向哥伦比娅。法尔伽赶来援救，旅行者等人则寻找另一枚虹月月髓，希望为她争取对抗狂猎的力量。月髓藏在一处与坎瑞亚旧史相连的秘境里，普通人无法轻易踏入。\u003c/p\u003e\n\u003cp\u003e愚人众执行官「仆人」阿蕾奇诺以赤月王朝后裔的身份相助。她与桑多涅、哥伦比娅并非怀着相同的愿望，却在此刻面对共同的危险。她以自己的力量打开道路，手也受到深渊侵蚀。旅行者得到的因此不是一件可随意使用的宝物，而是由数人承担代价才取得的一次机会。雷利尔的真正来历仍待查明。\u003c/p\u003e\n"},{"id":"v6.1-s1","title":"第四幕：回望湮灭的月光","kind":"chapter","html":"\u003cp\u003e奈芙尔追查坎瑞亚宫廷的旧档，拼出雷利尔成为「罪人」之前的人生。昔日的坎瑞亚王伊尔明曾命他清除赤月王朝的后裔；名单里竟有他的未婚妻索琳蒂丝。他曾与戴因斯雷布、莱茵多特等人试图救下维瑟弗尼尔，索琳蒂丝却坠入深渊。王命、故国与所爱之人一同崩塌，雷利尔终于接受深渊的力量。今日的狂猎既是灾厄的追兵，也是一名旧时代幸存者扭曲的执念。\u003c/p\u003e\n\u003cp\u003e奈芙尔用棋盒暂困雷利尔，给众人布置最后一搏的时间。阿贝多与已拥有人形的杜林帮助哥伦比娅承受月之力量；戴因斯雷布维系通往月的门扉。众人合力将雷利尔逐出提瓦特，才使挪德卡莱免于眼前的追猎。胜利没有抹去过去的伤：阿蕾奇诺的手、杜林对自身出身的疑虑，以及哥伦比娅与月之间越来越难割断的联系，都仍在他们身上。\u003c/p\u003e\n\u003cp\u003e雷利尔的故事令旅行者再一次看见坎瑞亚灾厄中的人并非只有敌人与受害者两种面孔。有人因悲伤投向深渊，也有人带着同样的旧伤，选择为眼前的人点灯。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Nation_That_Doesn%27t_Exist\"\u003e第三幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/An_Elegy_for_Faded_Moonlight\"\u003e第四幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E4%B9%8B%E6%AD%8C\"\u003e空月之歌中文幕名与任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.2","major":6,"minor":2,"title":"空月之歌第五、六幕：终北的夜行诗；散于晨雾的月芒","chapter":"空月之歌第5至6幕","sections":[{"id":"v6.2-s0","title":"第五幕：终北的夜行诗","kind":"chapter","html":"\u003cp\u003e雷利尔之乱过去约两个月，挪德卡莱准备迎来「祈月之夜」。哥伦比娅告诉旅行者：那夜月矩力最盛，她必须借机返回月亮；继续留在提瓦特，她会逐渐消失。菈乌玛虽不舍，也无法以族人的祈愿强留她。旅行者与朋友们于是筹备一场告别的节庆，让她带着这里的记忆离开。\u003c/p\u003e\n\u003cp\u003e古老亥珀波瑞亚人的虚影却在各地浮现，甚至出现旅行者那艘星间飞船的幻影。法尔伽、奈芙尔、阿贝多和杜林等人分头调查。那些身影重复着既定的历史，旅行者能与之交谈，却难以改变其结局。菲林斯亲眼经历过数百年前的灾祸，深知「看见过去」不等于「救下过去的人」。杜林同样从虚影中看见无法挽回的死亡。他既忧惧自己身上的深渊之力，又决定由自己去认识并驾驭它，而非任由出身定义未来。\u003c/p\u003e\n\u003cp\u003e随后哥伦比娅从银月之庭消失。艾莉丝亲自现身，指出三月的力量汇聚挪德卡莱，提瓦特边界因此不稳。更迫切的是，哥伦比娅并未真正离开：她在失去力量、身份和归属后，正被世界排斥，连形体也难以维持。仅有月髓不足以送她回家。众人必须找到能使她继续存在的「真名」，还要打通通往月亮的路。尼可带来亥珀波瑞亚遗迹的线索；旅行者、菈乌玛与阿蕾奇诺承担进入遗迹所需的月矩力试炼。哥伦比娅的意识一直在旁边目睹他们寻找，却已虚弱到无法随行。\u003c/p\u003e\n"},{"id":"v6.2-s1","title":"第六幕：散于晨雾的月芒","kind":"chapter","html":"\u003cp\u003e在尼可开启的古老虚影中，众人读到三月女神与提瓦特的断裂史。按尼可所述，龙王尼伯龙根曾使三月升起；后来他以深渊之力与天理再战，将月亮改为兵器，三月女神也因分歧和战争遭囚。天理击碎两月、把另一月逐出天外。壁画与口述让哥伦比娅为何难以在此世长存，有了更沉重的解释。\u003c/p\u003e\n\u003cp\u003e然而走遍遗迹，谁也找不到一份早已写下的「真名」。尼可反问众人：若过去从未有人为哥伦比娅命名，何不在今日由她认同的人呼唤她？旅行者、菈乌玛与阿蕾奇诺都呼唤「哥伦比娅」——那个曾是愚人众代号，如今却盛满共同回忆的名字。即将消散的少女听见了他们。她接受这个名字，为自己添上「希珀塞莱尼娅」，意为诞生于月下，也意为在这个世界获得新生。\u003c/p\u003e\n\u003cp\u003e祈月之夜终于成为一场真正的告别。哥伦比娅与朋友们同游那夏镇，在最热闹的灯火之后走向通月之门。门却被「博士」多托雷预先布下的伪月劫持。他利用虚影中堆积的「变数」与月之知识，让术法把哥伦比娅送到自己身边；三月之力落入他手中，周围的时间几乎停滞。旅行者独自迎战而不敌。哥伦比娅为破坏他的掌控，主动跃入未知的「月亮倒影」。多托雷失去完整力量而撤退，她却也没有回到原本的月亮。\u003c/p\u003e\n\u003cp\u003e众人从震惊中重新站起。流浪者揭穿伪月如何误导传送门，阿蕾奇诺、法尔伽、菈乌玛、奈芙尔、桑多涅与魔女会各担一方：寻找哥伦比娅，查清博士的下一步，并守护挪德卡莱。旅行者望向夜空，节日留下的糖与贺卡仍在手中；他们刚为一人找到名字，如今必须再把她找回来。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Nocturne_of_the_Far_North\"\u003e第五幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%95%A3%E4%BA%8E%E6%99%A8%E9%9B%BE%E7%9A%84%E6%9C%88%E8%8A%92\"\u003e第六幕中文任务\u003c/a\u003e：\u003ca href=\"https://wiki.biligame.com/ys/%E5%90%8D%E4%BA%8E%E4%BD%95%E5%A4%84%EF%BC%9F\"\u003e名于何处？\u003c/a\u003e、\u003ca href=\"https://wiki.biligame.com/ys/%E5%9B%9E%E5%88%B0%E6%9C%88%E4%BA%AE%E4%B8%8A%E5%8E%BB\"\u003e回到月亮上去\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.3","major":6,"minor":3,"title":"空月之歌第七、八幕：如果在冬夜，一个旅人；真实之月","chapter":"空月之歌第7至8幕","sections":[{"id":"v6.3-s0","title":"第七幕：如果在冬夜，一个旅人","kind":"chapter","html":"\u003cp\u003e哥伦比娅失踪后，阿蕾奇诺与桑多涅先行攻入博士的北方研究所。旅行者、法尔伽和菈乌玛等人循迹赶到，见到被焚毁的兵器、逃散的愚人众，以及博士长期制造人工月髓的证据。博士早料到众人会来。他以人工月髓修复战伤，连旅行者与阿蕾奇诺联手也无法将他击败；随后，他把同伴们送离，只将旅行者囚入自己的异空间。\u003c/p\u003e\n\u003cp\u003e博士想招揽这位来自世界之外的「降临者」。他声称能终结旅行者漫长的寻亲之路，质疑众人为何要遵从神定的命运。旅行者明知他话里藏着诱饵，仍留意其中有关世界规则的情报，等待脱身的机会。博士则在挪德卡莱制造能量界域，进行把人的意识移入动物身体等实验，以近乎残酷的方式试探其新权能。\u003c/p\u003e\n\u003cp\u003e地面上的盟友没有坐等。桑多涅发现博士在同行者身上埋下诅咒；法尔伽和霜月之子、执灯人疏散居民，阿蕾奇诺及愚人众把北方民众送往至冬，南方则向纳塔撤离。公子带来冰之女皇的授权：若博士已危及一切，阿蕾奇诺与桑多涅可以对他下杀手。杜林向蒙德求援，多莉向须弥送信，阿贝多、流浪者与魔女会研究那些界域。昔日立场相异的人，此刻都把保住一方土地放在首位。\u003c/p\u003e\n\u003cp\u003e月亮倒影中的哥伦比娅仍活着，却被困在逆流的时间里。她一次次触及过去：祈月夜为自己取名的记忆、旅行者身边未察觉的轻拍、书库中被挪动的典籍、昔日保护霜月之子的月矩力屏障。那些看似偶然的帮助，原来是她在未来冒险回望时留下的。她终于以部分灵魂创造月灵努昂诺塔，让它陪伴并引导过去的旅行者；而在今日，奈芙尔借它发现哥伦比娅仍在抗争。\u003c/p\u003e\n"},{"id":"v6.3-s1","title":"第八幕：真实之月","kind":"chapter","html":"\u003cp\u003e流浪者借阿贝多的炼金信号闯入博士的囚笼，救出旅行者。他暂放下亲手复仇的机会，因为众人的计划更需要旅行者活着。桑多涅则取枫丹的研究与月之知识推演「世界公式」，寻找把逆流中的哥伦比娅拉回此刻的方法。流浪者自愿以自己的核心接入地脉替她运算，明知意识可能被重置甚至失散。\u003c/p\u003e\n\u003cp\u003e哥伦比娅在时间尽头遇到雷利尔与索琳蒂丝残存的灵魂，也发现博士早曾利用雷利尔复生来布置今日的局。再往前，她见到被囚禁的三月女神。她们知道自己的结局，仍把权能交给后来者。哥伦比娅把身体化为散布在过去挪德卡莱的月光，灵魂寄于努昂诺塔，等待朋友们在未来重聚这三部分。奈芙尔曾准备以双目为代价窥见这段遥远往事；哥伦比娅的安排使她免受此伤。\u003c/p\u003e\n\u003cp\u003e决战时，博士以伪月之主的姿态撕开天空，在云上隔绝旅行者、菲林斯、菈乌玛和奈芙尔。他以为桑多涅的公式还差最后一步，便向旅行者施以致命一击。桑多涅替旅行者挡下，身体遭重创，仍把真实的计算留在机仆体内。博士误以为她死去便能截断公式，却没看见她让自己成为了诱饵。\u003c/p\u003e\n\u003cp\u003e阿蕾奇诺、法尔伽与尼可将真正的霜月牵引到提瓦特，击碎伪天的裂口；流浪者的核心完成余下运算。散在大地的月光、努昂诺塔携带的灵魂与三月权能汇合，哥伦比娅睁开双眼，从月下归来。她与旅行者夺回月髓，救出被隔绝的同伴，合力击碎博士的人工月髓。博士在这场战斗中的形体随之消散。胜利的欢呼到了桑多涅身边便止住了：哥伦比娅抱着她，终于明白朋友为自己付出的代价。\u003c/p\u003e\n\u003cp\u003e挪德卡莱各方结盟共治，霜月留在提瓦特。阿蕾奇诺依桑多涅的嘱托，带她与机仆的核心回枫丹处理后事；流浪者返回须弥。哥伦比娅则带旅行者登上霜月，找到当年双子乘坐的飞船。飞行记录显示，飞船曾在数千年前路过提瓦特，之后又返回并在挪德卡莱坠落。旅行者仍不知为何折返，却第一次站在当年离开与归来的器物前，坦承这片世界也已成为自己的家。哥伦比娅把部分月之恩泽还给大地，也松开了旅行者使用元素时受到的一些限制。\u003c/p\u003e\n"},{"id":"v6.3-s2","title":"此刻悬而未决","kind":"question","html":"\u003cp\u003e飞船为何返回？「博士」在这一战后的命运是否已经彻底定下？冰之女皇与至冬诸执行官各自要怎样使用神之心？旅行者带着这些仍未揭晓的问题，继续向北。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Traveler_on_a_Winter%27s_Night\"\u003e第七幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/True_Moon\"\u003e第八幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E5%A6%82%E6%9E%9C%E5%9C%A8%E5%86%AC%E5%A4%9C%EF%BC%8C%E4%B8%80%E4%B8%AA%E6%97%85%E4%BA%BA\"\u003e第七幕中文任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%9C%9F%E5%AE%9E%E4%B9%8B%E6%9C%88\"\u003e第八幕中文任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.4","major":6,"minor":4,"title":"无新增魔神任务","chapter":"无主线","sections":[{"id":"v6.4-s0","title":"本版纪事","kind":"chapter","html":"\u003cp\u003e博士的伪月之战已在上一版本落幕。6.4 没有新增魔神任务幕次，因此旅行者寻找血亲与前往至冬的主线，在这里暂歇。挪德卡莱的结盟与霜月归来，是此时已知的局面；这一页不预叙下一场危机。\u003c/p\u003e\n\u003cp\u003e本版新增法尔伽传说任务和两项世界任务，另有「捕风的归客」活动。它们不构成新的魔神任务章节，因此文件名依约标为「无」。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/Luna_V\"\u003e6.4／月之五版本新增任务\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.5","major":6,"minor":5,"title":"无新增魔神任务：山中好长日与空之神殿","chapter":"无主线","sections":[{"id":"v6.5-s0","title":"重要世界支线：山中好长日","kind":"world","html":"\u003cp\u003e本版没有新的魔神任务幕次，却开放了蒙德北境风息山与「空之神殿」。这条世界任务直接触及旅行者旅途开端的天空之谜，值得在编年中单列。\u003c/p\u003e\n\u003cp\u003e旅行者在山中一处废弃疗养院遇到寻找姐姐的少女。姐姐似乎已死，墓碑甚至让二人的相貌重叠；然而一名自称守望者的巨大神殿造物突然现身，将他们引向高悬于常世之外的空之神殿。那里由掌管空间的神明阿斯莫代创造。造主离去后，另一守望者梅兰塔把神殿变作囚笼，居民遭追猎，有的被困在画与书页里，有的化作沙尘。\u003c/p\u003e\n\u003cp\u003e少女一路拾回姐姐留下的画、书信与饰物。她逐渐知道，姐姐曾在神殿中与众人相识，也曾试图终止梅兰塔的统治。通往神殿核心的道路要求献出全部记忆；当年姐姐已经付过这笔代价，如今妹妹仍决定踏上同一条路。旅行者击败梅兰塔。那守望者终于承认：造主不在，造物早有选择去留的自由；他以「纠正」他人为名施暴，实则害怕失去造主的认可。神殿重获自由，少女却在回到地面时忘了自己所经历的一切。旅行者陪她重新开始，也保留姐姐可能仍在人世的希望。\u003c/p\u003e\n\u003cp\u003e这段旅程还为最初封印双子的陌生神明给出名字与领域：\u003cstrong\u003e阿斯莫代，空间之执政\u003c/strong\u003e。她究竟为何离开自己的神殿、为何阻止双子离开提瓦特，任务并未全部回答。旅行者知道了她是谁，却还不知道她在整盘棋中要守住什么。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/Luna_VI\"\u003e6.5／月之六版本新增区域与任务\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/A_Long_Day_in_the_Mountains\"\u003e山中好长日任务梗概\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.6","major":6,"minor":6,"title":"空月之歌第九、十幕：身土坏空，五蕴识转；虚空劫灰往世书","chapter":"空月之歌第9至10幕","sections":[{"id":"v6.6-s0","title":"第九幕：身土坏空，五蕴识转","kind":"chapter","html":"\u003cp\u003e柯莱写信求援。她梦见须弥城里人人身份错乱，连提纳里也不认识她；尼可的声音告诉她，那不是寻常噩梦。旅行者从挪德卡莱赶来时，梦中的灾厄已开始逼近：世界树无法正常收录和处理地脉信息，记忆与认知随之失序。纳西妲以自身承接堵塞的信息，直到力量耗尽昏迷。教令院与巡林官撤离民众，须弥人又一次在「智慧之国」里承受失去记忆与自我的恐惧。\u003c/p\u003e\n\u003cp\u003e旅行者想到草龙阿佩普曾受纳西妲救助，便带她前往沙漠求援。阿佩普把生命力量分给她，并指出世界树本是古龙时代之物，后来被天理接管与改造。纳西妲短暂醒来，交给旅行者一枚花形钥匙，留下只准他们独自保管的线索。另一边，贤者们试图重启曾由草神之心驱动的「虚空」系统，却必须寻找新能量，也必须阻止沙漠中突然兴起的镇灵风暴。\u003c/p\u003e\n\u003cp\u003e风暴把旅行者引回居尔城。他们与昔日同伴婕德重逢，唤醒镇灵利露帕尔。她平息镇灵暴乱，旧日沙漠之行在此成为救城之举。尼可和奈芙尔也在封锁前进入须弥；尼可揭示，柯莱体内当年被博士植入的神之残骸，来自花神娜布·玛莉卡塔，这才使她能以花神的祈词安抚镇灵。柯莱知道自己身上藏着古神的碎片，却仍是由今日的亲友与选择定义的柯莱。\u003c/p\u003e\n\u003cp\u003e众人重启赤王留下的「阿如」装置。古代七柱同意协助，让沙漠的古技术承担须弥新的守护。阿如短暂敞开，婕德得与父亲的灵魂再见一面。须弥诸人此时尚未找出幕后者，但已经把雨林、沙漠与古老的敌意暂且放下，准备共同抵御下一波灾难。\u003c/p\u003e\n"},{"id":"v6.6-s1","title":"第十幕：虚空劫灰往世书","kind":"chapter","html":"\u003cp\u003e真相从世界树的内部浮出：敌人借死亡进入地脉，绕过了纳西妲能设的防线。须弥城长出一株异常巨树，博士的实验在那里继续。他在挪德卡莱失去的那具形体并非全部；「富人」潘塔罗涅提供资金与接应，另一个博士的切片仍在世界树深处。须弥人要争回自己的记忆，也要决定世界树若已无法挽救，该把这个世界的知识托付给何处。\u003c/p\u003e\n\u003cp\u003e纳西妲制定大胆的计划：以重新启用的虚空系统让世界树停摆，再将信息转存至改造后的阿如。所需的火元素神之心由玛薇卡交出。为免计划被地脉记录、被博士提前读到，纳西妲借旅行者这个世界树无法记录的人与纳塔一侧沟通。艾尔海森、卡维和贤者改造阿如，赛诺、迪希雅、坎蒂丝、婕德等人从正面攻城；旅行者与流浪者则沿巨树潜入，直抵世界树深处。\u003c/p\u003e\n\u003cp\u003e博士认出流浪者被世界树抹去的旧身份，借其悔恨扰乱两人。流浪者仍选择守住当下，与旅行者掩护纳西妲转移信息。纳西妲在世界树中见到伊斯塔露、洛诺瓦和纳贝里士三位执政的意志，向她们说明自己的决定：若保护人类的树已遭彻底污染，就不能为了保留树而牺牲人。得到许可后，她点燃火神之心。烈焰沿根系烧毁世界树；博士企图拖旅行者同坠，却被自己那些憎恨原体的切片缠住。旅行者、流浪者与纳西妲终于脱身，博士的这一场实验在火中终结。\u003c/p\u003e\n\u003cp\u003e火烧了七昼夜。改造后的阿如承接了世界树储存信息的职责，纳西妲也脱离危险。须弥人开始修复家园，柯莱成为正式巡林员。尼可带利露帕尔来见她：镇灵替她吸走花神残骸，随后自己散去，终于与缔造她的旧日命运告别。旅行者见到的不只是一次技术上的替换，而是须弥从神的树下走向由众人共同守护的未来。\u003c/p\u003e\n\u003cp\u003e火神之心后来无迹可寻。更重要的问题也留了下来：世界失去旧有的世界树之后，阿如能否长久承受它曾担负的全部重量？旅行者仍要带着这份未知，继续寻找血亲。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/As_All_Falls_to_Emptiness\"\u003e第九幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Truth_Amongst_the_Pages_of_Purana\"\u003e第十幕任务与梗概\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E7%A9%BA%E6%9C%88%E4%B9%8B%E6%AD%8C\"\u003e空月之歌中文幕名与任务顺序\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"6.7","major":6,"minor":7,"title":"无新增魔神任务：桑多涅归乡与望月者计划","chapter":"无主线","sections":[{"id":"v6.7-s0","title":"枫丹：发条人偶回家","kind":"chapter","html":"\u003cp\u003e两条故事一在枫丹，一在霜月；它们都发生在上一场月之决战之后。\u003c/p\u003e\n\u003cp\u003e桑多涅曾在与「博士」的决战中挡在旅行者身前，机关之躯几乎尽毁。众人以为「木偶」已经死去，她却在枫丹重新启动：残存的核心与新显现的「星之楔」给了她第二次机会。她修补躯体，把普隆尼亚留下的算式纳入新身体，却发现核心里仍有无法靠计算消除的「错谬」。\u003c/p\u003e\n\u003cp\u003e枫丹的千灵节将至，芙宁娜等人正筹拍映影。桑多涅化名「吉约丹」回到故乡，借维恩歌莱号和水下勘察寻找阿兰·吉约丹晚年的旧居。旅行者与派蒙再见到她时，才知道那场牺牲并非故事的终点。她与他们同行，却仍回避哥伦比娅，也竭力把一切不合逻辑的情绪称作故障。\u003c/p\u003e\n\u003cp\u003e他们终于找到藏在枫丹水下的屋宅。花园、壁炉、工作台与旧照片，把传说中的「奇械公」还原成一个曾与她共同生活的人。阿兰在晚年因水仙十字院昔日的同伴雷内而怀着遗憾；他也早已预见枫丹水位会升高，为旧居留下防水机关。他留给桑多涅的，不只是「多维立体算式核心」，还有一封信。信里，他说自己从未只把她当作造物；逻辑与感情的冲突，恰是她需要认识的心。算式可以帮她看见自己的灵魂，但如何面对它，由她自己决定。\u003c/p\u003e\n\u003cp\u003e桑多涅依照算式走入镜中的内心。她看见阿兰去世、旧日茶会的人一个个离去、哥伦比娅走向月之门，以及普隆尼亚在决战中毁坏。这些失去使她害怕再有所爱。镜中的另一位「桑多涅」承载了她压下的哀伤与愿望；她本想像排除错误那样抹去对方，最终却击碎镜面，拥抱了她。所谓「错谬」原来与她同为一人。她从这里带走的答案，是即使终有告别，仍愿意珍惜眼前的人与短暂的美好。\u003c/p\u003e\n\u003cp\u003e\u003cimg src=\"https://static.wikia.nocookie.net/gensin-impact/images/9/95/Story_Teaser-_What_Reflects_Itself_in_Mirror-Water_-_Genshin_Impact/revision/latest?cb=20260708040015\" alt=\"桑多涅拥抱镜中的自己，出自官方故事短片画面\" /\u003e\u003c/p\u003e\n\u003cp\u003e\u003cem\u003e官方故事短片画面：桑多涅拥抱被她视作「错谬」的自己。\u003c/em\u003e\u003c/p\u003e\n\u003cp\u003e归乡并未止于私人记忆。桑多涅察觉露景泉附近有水仙十字结社旧术造成的残患：被「断魂」之术割裂的灵魂未能归入地脉，长久漂泊后又受怨意与污秽侵蚀。她与茜特菈莉、旅行者追查并净化那些游魂，也替阿兰与雷内留下的旧事补上一笔。映影拍摄临近落幕时，她终于与哥伦比娅重逢；镜头留下了拥抱。随后她来到阿兰墓前，承认自己很高兴曾成为他的家人。枫丹的旧故事，以一个真正学会回家的生命收束。\u003c/p\u003e\n"},{"id":"v6.7-s1","title":"霜月：望月者把声音送向星海","kind":"chapter","html":"\u003cp\u003e与此同时，旅行者与派蒙在挪德卡莱看见哥伦比娅的身影，追进杜南纳深坑附近的古设施。那身影其实是一只黑色月灵所化。它引他们启动遗迹，也引他们登上飞往霜月的船。旅行者给它起了亲近的称呼「黑蛋」。在霜月上，众人穿过古老能源站、月海与被遗弃的研究设施，寻到哥伦比娅，逐渐明白这些工程并非单为开采月之力而建。\u003c/p\u003e\n\u003cp\u003e月球背面仍立着严密守卫的龙族基地。记录表明，归来的漆黑龙王曾把月心凿作能源，让月球成为瞄准提瓦特的武器；在这一版已知的历史里，这件武器最终未能战胜天理。但基地更深处藏着另一群人的事业。伊比尼伯龙、乌吉恩、玛歌、卢沙里姆与宁宁等「望月者」曾探测星空，收到一个遥远文明发来的讯息。他们决定让那份声音继续远行，告诉未知的星海：这里也有生命，也有人愿意回应。\u003c/p\u003e\n\u003cp\u003e黑蛋的身世就在月心揭晓。她并非偶然闯入遗迹的月灵，而是月球意志利用望月者留下的信息孕育的新生命。许多前辈的记忆汇入她的使命；她来到月心，才知道自己要在望月者高塔启动最后的传讯。讯息穿越虚假之天，可能暴露提瓦特的位置。旅行者与哥伦比娅因此犹豫，黑蛋也愿意为朋友放弃使命。哥伦比娅提出以自己的月神之力掩护信号，遇险便将它抹除。风险无法被彻底证明不存在，但众人决定陪黑蛋完成这一次远航。\u003c/p\u003e\n\u003cp\u003e黑蛋向星空报出望月者的名字，愿别处的文明知道自己并不孤单。传讯结束，她的形体散去，只留下帽子。古老终端随之开启一段封存的回音：很久以前，在星海间旅行的旅行者与血亲曾收到过望月者的声音，其中一人向月球回信，称那道来自黑暗中的呼唤像篝火，约定有一天循声来访。回信因年代与距离而残缺，如今才在月球上重新被听见。旅行者的寻亲之路，忽然与这群早已逝去的观星者接在一起；至于星海外还有谁听见了新讯息，此刻无人知道。\u003c/p\u003e\n"},{"id":"v6.7-s2","title":"三月旧影：无人船","kind":"chapter","html":"\u003cp\u003e霜月上另有三艘无人驾驶的月船。旅行者登船时，听见三位旧日月之女神的回忆。她们本是龙王所托、守护世界的存在，却曾为了回应人类而化作人形；其中一位与伊斯塔露谈过时间的法则，三姐妹也曾偷偷走入人间节庆。后来，高天的秩序以残酷代价维系世界，龙与人都有人死去。她们并不否认黑暗的威胁，却为是否该服从这种秩序、能否救下每一个生命而争执。「希望」这个来自人类的词，成为对话最后仍未熄灭的微光。三段回忆展示了三月与人类、龙王及高天之间的旧日关系，也留下她们日后命运的疑问。\u003c/p\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/Luna_VIII\"\u003e6.7「月之八」版本内容与任务清单\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Sunny_Summer_Fontinalia\"\u003e「映夏！归乡？千灵节！」任务目录\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Those_We_Have_Lost_(Quest)\"\u003e「那些我们所失去的」任务正文\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/File:Story_Teaser-_What_Reflects_Itself_in_Mirror-Water_-_Genshin_Impact\"\u003e官方故事短片画面图库条目\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%9C%9B%E6%9C%88%EF%BC%88%E7%B3%BB%E5%88%97%E4%BB%BB%E5%8A%A1%EF%BC%89\"\u003e「望月」系列任务中文目录\u003c/a\u003e；\u003ca href=\"https://wiki.biligame.com/ys/%E6%9C%9B%E6%9C%88%E8%80%85%E8%AE%A1%E5%88%92\"\u003e「望月者计划」中文任务正文\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Moon_Gazing\"\u003e英文剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel\"\u003e「无人船」三段任务正文\u003c/a\u003e：\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel_(I)\"\u003e其一\u003c/a\u003e、\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel_(II)\"\u003e其二\u003c/a\u003e、\u003ca href=\"https://genshin-impact.fandom.com/wiki/The_Unmanned_Vessel_(III)\"\u003e其三\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"},{"version":"7.0","major":7,"minor":0,"title":"第七章第一至二幕：无神怜爱的雪国／死魂灵的夜曲","chapter":"第七章第1至2幕","sections":[{"id":"v7.0-s0","title":"第一幕：无神怜爱的雪国","kind":"chapter","html":"\u003ch3\u003e风雪中的来客\u003c/h3\u003e\n\u003cp\u003e离开挪德卡莱之前，哥伦比娅为旅行者和派蒙送行。旅途一路向北，终于抵达七国中最后一国——至冬。冰雪尚未给他们一个落脚的机会，派蒙便开始虚弱。狂风将二人冲散；旅行者跌入废弃列车所在的深谷，唤醒了古老装置「灰眸」。它认出旅行者是降临者，以日后相助为条件，借臻冰造物之力带旅行者穿过险境。\u003c/p\u003e\n\u003cp\u003e旅行者在雪屋中找到昏睡的派蒙，旁边守着一名有坎瑞亚星瞳的陌生人。那人没有回答自己的身份与派蒙的来历，只催旅行者先照顾她，便消失在风雪里。派蒙醒后认出他是愚人众的统括者「丑角」皮耶罗，却不记得自己与他曾有何交集。此刻最迫切的事，已不是觐见女皇，而是带派蒙求医。\u003c/p\u003e\n\u003cp\u003e灰眸驱动旧列车，载两人抵达凝露镇。镇民缺少取暖的晶矿，店铺闭门，寒冷仿佛从街巷渗进了每个人的生活。猎人阿罗夏收留派蒙，也让旅行者看到这片雪国的另一面：冰之女皇推行「严冬计划」，从民间压缩能源供应，将力量集中到一项重要研究；地方官员却趁分配之机私藏晶矿。旅行者与阿罗夏搜集证据，使贪墨者被捕，让原本属于居民的燃料回到他们手中。\u003c/p\u003e\n\u003cp\u003e前往皇都的列车意外坠入「影域」——一片缺少风、光和常规元素力的异境。灰眸替旅行者重整装备，众人才从暗影和魔物中挣脱。至冬之行甫一开始，旅行者已经知道：这里的危机并不只在风雪与饥寒，也有潜伏于世界缝隙中的异域。\u003c/p\u003e\n\u003ch3\u003e皇都与严冬计划\u003c/h3\u003e\n\u003cp\u003e列车驶进至冬堡。医生暂将派蒙的病视为受寒，药物却没能彻底驱散她的虚弱。旅行者寻访愚人众，从桑多涅处得知「公子」达达利亚如今还要代表属下参与至冬皇都评议会。桑多涅虽不愿陷在政事中，仍带旅行者前往彩冰镇救援矿工。在崩塌的矿洞里，旅行者与愚人众成员奥黛塔并肩击退魔物；一股新力量在旅行者手中凝成剑。其后，旅行者来到冰之七天神像前，终于与至冬的冰元素共鸣。\u003c/p\u003e\n\u003cp\u003e阿罗夏把旅行者引向秘密组织「呼啸社」。它的成员隐于普通职业之下，追查权势人物如何浪费或挪用国家的能源。剧院歌者沃雅妮莎也是其中一员。经她牵线，旅行者见到研究者米提亚，听说军械宫的实验正在大量消耗晶矿，试图从「星之楔」中获取新的能源。研究者已经出现难以解释的失忆；米提亚说到研究最终用途时，又被颈间异物强行阻断。派蒙则感到军械宫方向有某种力量正在影响自己。严冬计划的代价已经人人看见，真正的目的仍被封在高墙之内。\u003c/p\u003e\n\u003cp\u003e旅行者旁听了至冬皇都评议会。普契涅拉以全国用能为依据主张继续计划；达达利亚质问偏远地区和愚人众家属为何分得更少；潘塔罗涅则以维持大局回应。投票最终让计划以较窄优势延续。与此同时，神秘的「莱莱可」正通过潜入和威胁迫使权贵倒向反对票。桑多涅与达达利亚怀疑她就是奥黛塔：她的父亲曾在严冬计划早期死去，母亲从此再不能登台。旅行者持达达利亚的票，赴剧院观看奥黛塔的芭蕾试演，打算当面问清她的选择。\u003c/p\u003e\n"},{"id":"v7.0-s1","title":"第二幕：死魂灵的夜曲","kind":"chapter","html":"\u003ch3\u003e被风雪封住的舞台\u003c/h3\u003e\n\u003cp\u003e剧院上演《寻灵》。表演结束，暴风雪封住所有出口，观众与演员只得留宿。夜里，旅行者梦见黑雾追过螺旋楼梯，两人停下，随即被吞没。翌晨，梦中的两人果然死去，身上却没有寻常凶杀的痕迹。奥黛塔面对猜疑，公开承认自己就是「莱莱可」；她要揭露能源分配的不公，却与剧院中的死亡无关。风雪仍不止息，黑雾的梦一夜接着一夜，清晨的死者也一夜接着一夜。\u003c/p\u003e\n\u003cp\u003e众人查到一名没有入场票的佣兵施拉姆。他记忆中的至冬还停在数百年前，直到此时才忆起自己曾为保护恋人死在剧院。他是地脉留下的旧日亡魂，选择独自走进暴雪，希望断绝死亡；第二天的惨剧却仍发生。研究者米提亚也被奥黛塔目睹过死亡，却像活人一样走动，而且不记得死去的瞬间。他于是冒险离开，寻找剧院之外的真相。\u003c/p\u003e\n\u003cp\u003e剧院中还有被称作「冬妮娅」的少女。旅行者从未见过达达利亚的妹妹，旁人的记忆又各有缺口。真相揭开时，她忆起自己其实是很久以前因病死去的塔诗佳；工厂主楚古诺夫早已看出端倪，却因自己失去女儿，不忍拆穿。少女与众人告别，沃雅妮莎也在黑雾与夜祷的异境里，为守护旅行者耗尽自己。一个个离去的人，让这座舞台像被死亡挑选的世界。\u003c/p\u003e\n\u003ch3\u003e死之执政的目光\u003c/h3\u003e\n\u003cp\u003e米提亚从暴雪中归来，提出骇人的推断：剧院里的人或许都已死去，只是不知道自己身在何处。他手上的红眼印记，使旅行者认出「死之执政」若娜瓦的象征。同行多日的阿罗夏忽然变了声调；借他形貌站在众人面前的，正是若娜瓦。她把剧院变作观看死亡之戏的场所，也让众人落入「死之诅咒」。地脉原本能牵引灵魂，剧院附近经改造的地脉却妨碍她处理死者；降临者的灵魂又不能像提瓦特之人那样被纳入地脉。旅行者与米提亚反击她的显现，众人才从那场如梦的死境中醒来。\u003c/p\u003e\n\u003cp\u003e醒来不是终局。皮耶罗趁旅行者被困剧院，已将派蒙带往军械宫救治。旅行者与奥黛塔赶去时，死之诅咒再次发动；奥黛塔以自身之力替旅行者挡下一次死亡。军械宫里遍地倒下的人，显示诅咒并未只笼罩剧院。若娜瓦亲自现身，向派蒙伸手，皮耶罗挡住了她。旅行者奋力出剑，仍难撼动执政，只以风元素在她身上留下一道浅伤。若娜瓦离去，威胁却没有消失。\u003c/p\u003e\n\u003cp\u003e皮耶罗终于说出他所知的旧事：派蒙来自天空岛，曾被带到坎瑞亚，作为礼物献给国王伊尔明；当年的国王并未重视她。她至少经历了五百年前的大灾变，自己却没有那段记忆。皮耶罗曾对此冷漠，如今却把派蒙视为坎瑞亚旧时代尚存的一丝清明。若娜瓦也指出，派蒙虽出自天空岛，却不具备它的权柄。皮耶罗治好了她在至冬的异状；旅行者与派蒙终于重逢。然而，这段身世还远未解释她究竟是谁。\u003c/p\u003e\n\u003cp\u003e\u003cimg src=\"https://patchwiki.biligame.com/images/ys/thumb/a/a1/7l9fnlyb0s0o6d9y0ot7btvotbc3h7s.png/1100px-%E9%AD%94%E7%A5%9E%E4%BB%BB%E5%8A%A1-%E6%A7%B2%E5%AF%84%E7%94%9F-CG1-%E7%A9%BA.png\" alt=\"旅行者在军械宫与派蒙重逢，游戏内《槲寄生》剧情画面\" /\u003e\u003c/p\u003e\n\u003cp\u003e\u003cem\u003e游戏内剧情 CG：历经剧院死境后，旅行者终于回到派蒙身边。画面采用旅行者「空」的版本。\u003c/em\u003e\u003c/p\u003e\n\u003cp\u003e米提亚说明「槲寄生计划」的危险：一旦技术突破有可能威胁天空岛，死之诅咒便会降下，使附近的人短暂死去，又在复生后失去记忆。剧院之祸正与他在表演时触及新的研究思路有关。皮耶罗同意暂缓计划，直到能对付若娜瓦；他也坦言愚人众与女皇要挑战天理。为了保护派蒙，旅行者选择暂与他们站在同一战线上。皮耶罗向二人展示了名为「槲寄生」的武器：严冬计划集中全国资源，挪德卡莱的研究制造它，军械宫则从第三降临者与星之楔的相关能量中寻找足以对抗天空岛的力量。至冬的诸多计划至此汇成一条线，但武器能否奏效仍无人知晓。\u003c/p\u003e\n\u003cp\u003e风雪暂时平息。严冬计划随之暂停，楚古诺夫关闭了吞噬能源的工厂，奥黛塔在「女士」墓前告别旧日师长，也重新选择自己的道路。旅行者与派蒙在街头再见达达利亚及真正的冬妮娅。人群忽然欢呼：冰之女皇结束东行讨伐，带着侍从回到至冬堡。她没有对旅行者说话，径直走向宫殿。七国最后一位神明终于近在眼前，真正的会面却尚未到来。\u003c/p\u003e\n"},{"id":"v7.0-s2","title":"重要世界任务：灰眸与古代沙皇的遗业","kind":"world","html":"\u003cp\u003e主线列车上结识的「灰眸」，在至冬的世界任务中引旅行者追寻自己被分离的三份力量。这条线索先通向白桦雪葬的旧王宫：王宫既是古代沙皇（Belyi Tsar）生前的居所，也是他的陵墓。传说他曾让人类与雪国异族同入宫廷，点燃为至冬带来温暖的火；约五百年前，他在抵御深渊与兽潮时战死，遗体归葬，部分血肉与「沙皇的白桦」相连。宫殿之下，旅行者发现名为「赫维格尔米尔」的秘密研究设施。古老记录提到一枚孕育「原人」的卵，也留下以生命炼金制造异兽的痕迹。守墓的双首兽兹韦尔曾是失败的造物，却得到沙皇庇护，因此数百年守在旧主身旁。它警告旅行者：「灰眸」同样是被造出来的容器，失去的记忆中藏着危险。\u003c/p\u003e\n\u003cp\u003e另一份力量埋在焰羽谷的奥库罗夫。旅行者把头上长出枝杈的少女娜丝佳（Nastya）送回故乡，却发现整座镇正被「医生」改造成树一样的生命。孩子把怪异的树人叫作家人，把同化称为回家；不合群的人则会被当作害虫。所谓「医生」其实是生物炼金术士柯西（Koshchei），他以「完美之树」许诺没有争执和痛苦的永生，代价是人的语言、意志与独特的爱逐渐消失。娜丝佳明知外面还有未来，仍为了再见母亲而走向树心，化作其中的一部分。旅行者无法替她作选择，只能见证这份悲愿如何被永恒的承诺吞没。此后，曾侍奉古代沙皇的阿克西妮娅现身；她与柯西都曾参与创造「灰眸」，并催促旅行者让它取回力量。\u003c/p\u003e\n\u003cp\u003e第三份力量牵出「爱憎的赫斯珀利德斯」一役。古代人造出的雪国异族并非完整生命，公主帕芙琳娜（Pavlina）为族人寻找摆脱缺陷的道路，试图以灰眸的力量完成仪式。旅行者与阿克西妮娅登上霜峰，阻止她把那力量献给族人。帕芙琳娜质问阿克西妮娅：所谓永恒的爱，是否会把没有资格进入理想国的人再次抛下？阿克西妮娅则认为，为了少数族人的未来耗尽一份足以改变世界的力量，太过狭隘。两人曾是同路者，如今各自以「拯救」之名选择了不同的牺牲。帕芙琳娜消散，碎片回到灰眸手中；她的诘问却留到了终局。\u003c/p\u003e\n\u003cp\u003e三份碎片齐聚，众人来到「无忧庭院」。阿克西妮娅揭开计划的真容：「灰眸」本是能完成「原初之人」的钥匙；那具躯壳，则与古代沙皇遗留下的身体和更古老的龙族血肉有关。旧时代的实验曾使一片国土坠入影域，让至冬陷入酷寒；如今她还想让整个世界进入影域，冻结时间对爱、喜悦与相聚的侵蚀。她许诺一个没有痛苦和嫉妒的明天，却也要让生命不再改变。\u003c/p\u003e\n\u003cp\u003e力量归位后的「灰眸」以「原初之人」的形态苏醒，却并不愿让那场改造发生。它早已预见阿克西妮娅会把自己排除在理想国之外，故意拆散力量、引导旧日同伴背离她，为旅行者争得阻止计划的机会。旅行者先后击败阿克西妮娅与「原初之人」；旧列车也在决战中依照灰眸留下的最终协议前来援助。庞然之躯崩落后，两人一同沉入影域。阿克西妮娅终于承认：相信爱的人，不必因为害怕失去就把一切封死。旅行者与派蒙带着失去朋友的沉重离开；那枚空下来的「灰眸」装置，只剩机械的应答。\u003c/p\u003e\n\u003cp\u003e这条支线让至冬的风雪与影域有了更古老的根源，也让贯穿主线的「永恒」问题再度出现：若要留住爱，是否必须让世界停止变化？在 7.0 的结局里，旅行者已经作答，但那答案不能替每一个人免去失去的痛苦。\u003c/p\u003e\n"},{"id":"v7.0-s3","title":"此时悬而未决","kind":"question","html":"\u003cul\u003e\n\u003cli\u003e严冬计划与「槲寄生计划」究竟要怎样挑战天理？皮耶罗展示的武器会付出什么代价？\u003c/li\u003e\n\u003cli\u003e若娜瓦为何盯上派蒙？派蒙从天空岛来到坎瑞亚之后，又经历了什么？\u003c/li\u003e\n\u003cli\u003e影域、灰眸和至冬的新技术，与旧世界的规则究竟有多深的联系？\u003c/li\u003e\n\u003c/ul\u003e\n"}],"sources":"\u003cul\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Version/7.0\"\u003e7.0 版本内容与任务清单\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%97%A0%E7%A5%9E%E6%80%9C%E7%88%B1%E7%9A%84%E9%9B%AA%E5%9B%BD\"\u003e第七章第一幕中文任务目录\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Everwinter_Without_Mercy\"\u003e第一幕英文剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%AD%BB%E9%AD%82%E7%81%B5%E7%9A%84%E5%A4%9C%E6%9B%B2%EF%BC%88%E7%B3%BB%E5%88%97%E4%BB%BB%E5%8A%A1%EF%BC%89\"\u003e第七章第二幕中文任务目录\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Wraith%27s_Nocturne\"\u003e第二幕英文剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://wiki.biligame.com/ys/%E6%A7%B2%E5%AF%84%E7%94%9F\"\u003e「槲寄生」中文任务正文与剧情 CG\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/On_One_Side_a_Palace,_On_the_Other_a_Tomb\"\u003e「一边是宫殿一边是陵阙」剧情概要\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/In_the_Dwelling_of_Life\"\u003e「在生命的寓所」剧情概要\u003c/a\u003e\u003c/li\u003e\n\u003cli\u003e\u003ca href=\"https://genshin-impact.fandom.com/wiki/Hesperides_of_Love_and_Hate\"\u003e「爱憎的赫斯珀利德斯」任务目录\u003c/a\u003e与\u003ca href=\"https://genshin-impact.fandom.com/wiki/Bell_Ringing_at_Dusk\"\u003e终章正文\u003c/a\u003e；\u003ca href=\"https://genshin-impact.fandom.com/wiki/Her_Palace_Collapses_Into_the_Blizzard\"\u003e「她的宫殿正坍塌向风雪」剧情概要\u003c/a\u003e；\u003ca href=\"https://wiki.biligame.com/ys/%E5%A5%B9%E7%9A%84%E5%AE%AB%E6%AE%BF%E6%AD%A3%E5%9D%8D%E5%A1%8C%E5%90%91%E9%A3%8E%E9%9B%AA\"\u003e中文任务目录\u003c/a\u003e\u003c/li\u003e\n\u003c/ul\u003e\n"}]};
